const duasDB = [

/* ---------- WAKING UP ---------- */
{ id: 1,   category: "Waking Up", arabic: "الْحَمْدُ لِلَّهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا وَإِلَيْهِ النُّشُورُ", urdu: "شکر ہے اللہ کا جس نے ہمیں موت کے بعد زندگی دی اور اسی کی طرف اٹھ کر جانا ہے۔", translit: "Alhamdulillahil-ladhi ahyana ba'da ma amatana wa ilayhin-nushur" },
{ id: 2,   category: "Waking Up", arabic: "الْحَمْدُ لِلَّهِ الَّذِي رَدَّ عَلَيَّ رُوحِي، وَعَافَانِي فِي جَسَدِي، وَأَذِنَ لِي بِذِكْرِهِ", urdu: "شکر ہے اللہ کا جس نے میری روح لوٹائی، میرے جسم کو عافیت دی اور مجھے اپنے ذکر کی اجازت دی۔", translit: "Alhamdulillahil-ladhi radda 'alayya ruhi, wa 'afani fi jasadi, wa adhina li bi dhikrih" },
{ id: 3,   category: "Waking Up", arabic: "لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ", urdu: "اللہ کے سوا کوئی معبود نہیں، وہ اکیلا ہے، اس کا کوئی شریک نہیں، بادشاہت اسی کی اور حمد اسی کے لیے ہے اور وہ ہر چیز پر قادر ہے۔", translit: "La ilaha illallahu wahdahu la sharika lahu, lahul-mulku wa lahul-hamdu, wa huwa 'ala kulli shay'in qadir" },
{ id: 4,   category: "Waking Up", arabic: "اللَّهُمَّ بِكَ أَصْبَحْنَا وَبِكَ أَمْسَيْنَا، وَبِكَ نَحْيَا وَبِكَ نَمُوتُ وَإِلَيْكَ النُّشُورُ", urdu: "اے اللہ! تیرے ہی ساتھ ہم نے صبح کی اور تیرے ہی ساتھ شام کی، تیرے ہی ساتھ جیتے ہیں اور تیرے ہی ساتھ مرتے ہیں اور تیری ہی طرف اٹھ کر جانا ہے۔", translit: "Allahumma bika asbahna wa bika amsayna, wa bika nahya wa bika namutu wa ilaykan-nushur" },
{ id: 5,   category: "Waking Up", arabic: "اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ وَأَبُوءُ بِذَنْبِي فَاغْفِرْ لِي فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ", urdu: "اے اللہ! تو ہی میرا رب ہے، تیرے سوا کوئی معبود نہیں، تو نے مجھے پیدا کیا اور میں تیرا بندہ ہوں، میں اپنی استطاعت بھر تیرے عہد و وعدے پر قائم ہوں۔ میں اپنے عمل کے شر سے تیری پناہ مانگتا ہوں۔ میں تیری نعمت کا اقرار کرتا ہوں اور اپنے گناہ کا اعتراف کرتا ہوں، پس مجھے معاف فرما، کیونکہ گناہ صرف تو ہی معاف کرتا ہے۔", translit: "Allahumma anta rabbi la ilaha illa anta khalaqtani wa ana 'abduka, wa ana 'ala 'ahdika wa wa'dika mastata't, a'udhu bika min sharri ma sana't, abu'u laka bini'matika 'alayya wa abu'u bi dhanbi faghfir li fa innahu la yaghfirudh-dhunuba illa anta" },
{ id: 6,   category: "Waking Up", arabic: "أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلَّهِ، وَالْحَمْدُ لِلَّهِ، لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ", urdu: "ہم نے صبح کی اور ساری بادشاہت اللہ ہی کے لیے ہے، تمام حمد اللہ کے لیے ہے، اللہ کے سوا کوئی معبود نہیں، وہ اکیلا ہے اس کا کوئی شریک نہیں۔", translit: "Asbahna wa asbahal-mulku lillah, wal-hamdu lillah, la ilaha illallahu wahdahu la sharika lahu" },
{ id: 7,   category: "Waking Up", arabic: "اللَّهُمَّ مَا أَصْبَحَ بِي مِنْ نِعْمَةٍ أَوْ بِأَحَدٍ مِنْ خَلْقِكَ فَمِنْكَ وَحْدَكَ لَا شَرِيكَ لَكَ، فَلَكَ الْحَمْدُ وَلَكَ الشُّكْرُ", urdu: "اے اللہ! جو نعمت بھی صبح ہوئی، مجھ پر ہو یا تیری کسی مخلوق پر، وہ صرف تیری طرف سے ہے، تیرا کوئی شریک نہیں، تیرے لیے حمد اور تیرے لیے شکر ہے۔", translit: "Allahumma ma asbaha bi min ni'matin aw bi ahadin min khalqika faminka wahdaka la sharika laka, falakal-hamdu wa lakash-shukr" },
{ id: 8,   category: "Waking Up", arabic: "اللَّهُمَّ عَافِنِي فِي بَدَنِي، اللَّهُمَّ عَافِنِي فِي سَمْعِي، اللَّهُمَّ عَافِنِي فِي بَصَرِي، لَا إِلَهَ إِلَّا أَنْتَ", urdu: "اے اللہ! میرے جسم کو عافیت دے، میرے کان کو عافیت دے، میری آنکھ کو عافیت دے، تیرے سوا کوئی معبود نہیں۔", translit: "Allahumma 'afini fi badani, Allahumma 'afini fi sam'i, Allahumma 'afini fi basari, la ilaha illa anta" },

/* ---------- SLEEPING ---------- */
{ id: 9,   category: "Sleeping", arabic: "بِاسْمِكَ اللَّهُمَّ أَمُوتُ وَأَحْيَا", urdu: "اے اللہ! تیرے نام کے ساتھ میں مرتا اور جیتا ہوں۔", translit: "Bismika allahumma amutu wa ahya" },
{ id: 10,  category: "Sleeping", arabic: "اللَّهُمَّ قِنِي عَذَابَكَ يَوْمَ تَبْعَثُ عِبَادَكَ", urdu: "اے اللہ! مجھے اس دن کے عذاب سے بچا جس دن تو اپنے بندوں کو اٹھائے گا۔", translit: "Allahumma qini 'adhabaka yawma tab'athu 'ibadaka" },
{ id: 11,  category: "Sleeping", arabic: "الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنَا وَسَقَانَا وَكَفَانَا وَآوَانَا، فَكَمْ مِمَّنْ لَا كَافِيَ لَهُ وَلَا مُؤْوِيَ", urdu: "شکر ہے اللہ کا جس نے ہمیں کھلایا، پلایا، کفایت کیا اور پناہ دی، کتنے ہی لوگ ہیں جن کا نہ کوئی کفایت کرنے والا ہے نہ پناہ دینے والا۔", translit: "Alhamdulillahil-ladhi at'amana wa saqana wa kafana wa awana, fakam mimman la kafiya lahu wa la mu'wiya" },
{ id: 12,  category: "Sleeping", arabic: "اللَّهُمَّ أَسْلَمْتُ نَفْسِي إِلَيْكَ، وَوَجَّهْتُ وَجْهِي إِلَيْكَ، وَفَوَّضْتُ أَمْرِي إِلَيْكَ، وَأَلْجَأْتُ ظَهْرِي إِلَيْكَ، رَغْبَةً وَرَهْبَةً إِلَيْكَ، لَا مَلْجَأَ وَلَا مَنْجَا مِنْكَ إِلَّا إِلَيْكَ، آمَنْتُ بِكِتَابِكَ الَّذِي أَنْزَلْتَ وَبِنَبِيِّكَ الَّذِي أَرْسَلْتَ", urdu: "اے اللہ! میں نے اپنی جان تیرے سپرد کی، اپنا چہرہ تیری طرف کیا، اپنا معاملہ تجھے سونپا، تیری رغبت اور خوف میں اپنی پشت تیرے پاس چھپائی، تیرے سوا نہ کوئی پناہ ہے نہ نجات۔ میں تیری نازل کردہ کتاب اور تیرے بھیجے ہوئے نبی پر ایمان لایا۔", translit: "Allahumma aslamtu nafsi ilayka, wa wajjahtu wajhi ilayka, wa fawwadtu amri ilayka, wa alja'tu zahri ilayka, raghbatan wa rahbatan ilayka, la malja'a wa la manja minka illa ilayka, amantu bikitabikal-ladhi anzalta wa binabiyyikal-ladhi arsalta" },
{ id: 13,  category: "Sleeping", arabic: "قُلْ هُوَ اللَّهُ أَحَدٌ، قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ، قُلْ أَعُوذُ بِرَبِّ النَّاسِ", urdu: "سورۃ الاخلاص، سورۃ الفلق اور سورۃ الناس پڑھنا — یہ تینوں سورتیں ہر شام اور سونے سے پہلے پڑھیں، یہ ہر چیز کے شر سے محافظ ہیں۔", translit: "Qul huwa Allahu ahad, Qul a'udhu bi rabbil-falaq, Qul a'udhu bi rabbin-nas" },
{ id: 14,  category: "Sleeping", arabic: "اللَّهُمَّ خَلَقْتَ نَفْسِي وَأَنْتَ تَوَفَّاهَا، لَكَ مَمَاتُهَا وَمَحْيَاهَا، إِنْ أَحْيَيْتَهَا فَاحْفَظْهَا وَإِنْ أَمَتَّهَا فَاغْفِرْ لَهَا، اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَافِيَةَ", urdu: "اے اللہ! تو نے میری جان بنائی اور تو ہی اسے وفات دیتا ہے، اسی کے لیے اس کی موت و حیات ہے، اگر تو نے اسے زندہ رکھا تو حفاظت فرما اور اگر وفات دی تو معاف فرما۔ اے اللہ! میں تجھ سے عافیت کا سوال کرتا ہوں۔", translit: "Allahumma khalaqta nafsi wa anta tawaffaha, laka mamatuha wa mahyaha, in ahyaytaha fahfazha wa in amattaha faghfir laha, Allahumma inni as'alukal-'afiyah" },
{ id: 15,  category: "Sleeping", arabic: "سُبْحَانَ اللَّهِ وَالْحَمْدُ لِلَّهِ وَاللَّهُ أَكْبَرُ", urdu: "ہر ایک (سبحان الله، الحمد لله، الله أكبر) تینتیس تینتیس مرتبہ سونے سے پہلے پڑھنا۔", translit: "Subhanallahi walhamdu lillahi wallahu akbar" },
{ id: 16,  category: "Sleeping", arabic: "بِاسْمِكَ رَبِّي وَضَعْتُ جَنْبِي، وَبِكَ أَرْفَعُهُ، فَإِنْ أَمْسَكْتَ نَفْسِي فَارْحَمْهَا، وَإِنْ أَرْسَلْتَهَا فَاحْفَظْهَا بِمَا تَحْفَظُ بِهِ عِبَادَكَ الصَّالِحِينَ", urdu: "اے میرے رب! تیرے نام کے ساتھ میں نے اپنا پہلو رکھا اور تیرے ہی نام سے اٹھاؤں گا، اگر تو نے میری جان روک لی تو اس پر رحم فرما، اور اگر چھوڑی تو اسے بچا جیسے تو اپنے نیک بندوں کو بچاتا ہے۔", translit: "Bismika rabbi wada'tu janbi, wa bika arfa'uh, fa in amsakta nafsi farhamha, wa in arsaltaha fahfazha bima tahfazu bihi 'ibadakas-salihin" },
{ id: 17,  category: "Sleeping", arabic: "اللَّهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ ... (آيَةُ الْكُرْسِيِّ)", urdu: "آیۃ الکرسی کا پڑھنا — جو سونے سے پہلے آیۃ الکرسی پڑھتا ہے، اس پر صبح تک اللہ کی طرف سے ایک محافظ مقرر رہتا ہے اور شیطان اس کے قریب نہیں آتا۔", translit: "Allahu la ilaha illa huwal-hayyul-qayyum (Ayatul Kursi)" },
{ id: 18,  category: "Sleeping", arabic: "اللَّهُمَّ نَوِّرْ قَلْبِي وَنُورًا فِي قَبْرِي، وَنُورًا بَيْنَ يَدَيَّ، وَنُورًا مِنْ خَلْفِي، وَنُورًا عَنْ يَمِينِي، وَنُورًا عَنْ شِمَالِي، وَنُورًا مِنْ فَوْقِي، وَنُورًا مِنْ تَحْتِي، وَأَعْظِمْ لِي نُورًا", urdu: "اے اللہ! میرے دل کو نور عطا فرما، میری قبر میں نور، میرے آگے، پیچھے، دائیں، بائیں، اوپر اور نیچے نور عطا فرما اور میرا نور بڑھا دے۔", translit: "Allahumma nawwir qalbi wa nuran fi qabri, wa nuran bayna yadayya, wa nuran min khalfi, wa nuran 'an yamini, wa nuran 'an shimali, wa nuran min fawqi, wa nuran min tahti, wa a'zim li nura" },

/* ---------- WUDU & SALAH ---------- */
{ id: 19,  category: "Wudu & Salah", arabic: "بِسْمِ اللَّهِ", urdu: "اللہ کے نام سے (وضو شروع کرتے وقت)۔", translit: "Bismillah" },
{ id: 20,  category: "Wudu & Salah", arabic: "اللَّهُمَّ اغْفِرْ لِي ذَنْبِي، وَوَسِّعْ لِي فِي دَارِي، وَبَارِكْ لِي فِي رِزْقِي", urdu: "اے اللہ! میرا گناہ معاف فرما، میرے گھر میں کشادگی عطا فرما اور میرے رزق میں برکت دے۔", translit: "Allahumma-ghfir li dhambi, wa wassi' li fi dari, wa barik li fi rizqi" },
{ id: 21,  category: "Wudu & Salah", arabic: "أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ", urdu: "میں گواہی دیتا ہوں کہ اللہ کے سوا کوئی معبود نہیں، وہ اکیلا ہے اس کا کوئی شریک نہیں، اور گواہی دیتا ہوں کہ محمد صلی اللہ علیہ وسلم اس کے بندے اور رسول ہیں۔", translit: "Ash-hadu an la ilaha illallahu wahdahu la sharika lahu, wa ash-hadu anna Muhammadan 'abduhu wa rasuluh" },
{ id: 22,  category: "Wudu & Salah", arabic: "اللَّهُمَّ إِنِّي أَسْأَلُكَ رِزْقًا طَيِّبًا وَعَمَلًا مُتَقَبَّلًا وَعِلْمًا نَافِعًا", urdu: "اے اللہ! میں تجھ سے پاکیزہ رزق، قبول شدہ عمل اور نفع بخش علم کا سوال کرتا ہوں۔", translit: "Allahumma inni as'aluka rizqan tayyiban wa 'amalan mutaqabbalan wa 'ilman nafi'an" },
{ id: 23,  category: "Wudu & Salah", arabic: "سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، وَتَبَارَكَ اسْمُكَ، وَتَعَالَى جَدُّكَ، وَلَا إِلَهَ غَيْرُكَ", urdu: "اے اللہ! پاک ہے تو، حمد تیرے لیے، تیرا نام بابرکت، تیری شان بلند ہے اور تیرے سوا کوئی معبود نہیں۔", translit: "Subhanaka allahumma wa bihamdika, wa tabaraka-smuka, wa ta'ala jadduka, wa la ilaha ghayruk" },
{ id: 24,  category: "Wudu & Salah", arabic: "رَبِّ اغْفِرْ لِي", urdu: "اے میرے رب! مجھے معاف فرما (دونوں سجدوں کے درمیان پڑھنا)۔", translit: "Rabbighfir li" },
{ id: 25,  category: "Wudu & Salah", arabic: "اللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ مِلْءَ السَّمَاوَاتِ وَمِلْءَ الْأَرْضِ وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ", urdu: "اے اللہ! تیرے لیے حمد ہے جتنا آسمان بھرے، زمین بھرے اور اس کے بعد جتنا تو چاہے۔", translit: "Allahumma rabbana lakal-hamdu mil'as-samawati wa mil'al-ardi wa mil'a ma shi'ta min shay'in ba'd" },
{ id: 26,  category: "Wudu & Salah", arabic: "اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ", urdu: "اے اللہ! محمد صلی اللہ علیہ وسلم اور آلِ محمد پر رحمت بھیج جیسے تو نے ابراہیم اور آلِ ابراہیم پر بھیجی، بیشک تو تعریف کے لائق اور بزرگی والا ہے۔", translit: "Allahumma salli 'ala Muhammadin wa 'ala ali Muhammadin kama sallayta 'ala Ibrahima wa 'ala ali Ibrahima, innaka hamidun majid" },
{ id: 27,  category: "Wudu & Salah", arabic: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ جَهَنَّمَ، وَمِنْ عَذَابِ الْقَبْرِ، وَمِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ، وَمِنْ شَرِّ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ", urdu: "اے اللہ! میں جہنم کے عذاب، قبر کے عذاب، زندگی و موت کی آزمائش اور دجال کے فتنے سے تیری پناہ مانگتا ہوں۔", translit: "Allahumma inni a'udhu bika min 'adhabi jahannam, wa min 'adhabil-qabr, wa min fitnatil-mahya wal-mamat, wa min sharri fitnatil-masihid-dajjal" },
{ id: 28,  category: "Wudu & Salah", arabic: "اللَّهُمَّ أَعِنِّي عَلَى ذِكْرِكَ وَشُكْرِكَ وَحُسْنِ عِبَادَتِكَ", urdu: "اے اللہ! اپنے ذکر، شکر اور اچھی عبادت پر میری مدد فرما۔", translit: "Allahumma a'inni 'ala dhikrika wa shukrika wa husni 'ibadatik" },
{ id: 29,  category: "Wudu & Salah", arabic: "اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي دِينِي وَدُنْيَايَ وَأَهْلِي وَمَالِي", urdu: "اے اللہ! میں تجھ سے معافی اور عافیت کا سوال کرتا ہوں اپنے دین، دنیا، اہل اور مال کے معاملے میں۔", translit: "Allahumma inni as'alukal-'afwa wal-'afiyah fi dini wa dunyaya wa ahli wa mali" },
{ id: 30,  category: "Wudu & Salah", arabic: "اللَّهُمَّ اغْفِرْ لِي مَا قَدَّمْتُ وَمَا أَخَّرْتُ، وَمَا أَسْرَرْتُ وَمَا أَعْلَنْتُ، وَمَا أَسْرَفْتُ، وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي، أَنْتَ الْمُقَدِّمُ وَأَنْتَ الْمُؤَخِّرُ لَا إِلَهَ إِلَّا أَنْتَ", urdu: "اے اللہ! میرے اگلے پچھلے، چھپے کھلے اور زیادتی کے گناہ اور جو گناہ تو مجھ سے زیادہ جانتا ہے، سب معاف فرما۔ تو ہی آگے کرنے والا اور پیچھے کرنے والا ہے، تیرے سوا کوئی معبود نہیں۔", translit: "Allahumma-ghfir li ma qaddamtu wa ma akkhartu, wa ma asrartu wa ma a'lantu, wa ma asraftu, wa ma anta a'lamu bihi minni, antal-muqaddimu wa antal-mu'akhkhiru la ilaha illa anta" },
{ id: 31,  category: "Wudu & Salah", arabic: "اللَّهُمَّ إِنِّي أَسْأَلُكَ بِأَنَّ لَكَ الْحَمْدَ لَا إِلَهَ إِلَّا أَنْتَ الْمَنَّانُ بَدِيعُ السَّمَاوَاتِ وَالْأَرْضِ، يَا ذَا الْجَلَالِ وَالْإِكْرَامِ", urdu: "اے اللہ! میں تجھ سے سوال کرتا ہوں، حمد تیرے لیے ہے، تیرے سوا کوئی معبود نہیں، تو منان، آسمانوں و زمین کا پیدا کرنے والا، اے جلال و کرم والے!", translit: "Allahumma inni as'aluka bi anna lakal-hamda la ilaha illa antal-mannan badi'us-samawati wal-ard, ya dhal-jalali wal-ikram" },

/* ---------- EATING & DRINKING ---------- */
{ id: 32,  category: "Eating & Drinking", arabic: "بِسْمِ اللَّهِ", urdu: "اللہ کے نام سے (کھانے سے پہلے)۔", translit: "Bismillah" },
{ id: 33,  category: "Eating & Drinking", arabic: "بِسْمِ اللَّهِ وَبَرَكَةِ اللَّهِ", urdu: "اللہ کے نام سے اور اللہ کی برکت کے ساتھ۔", translit: "Bismillahi wa barakatillah" },
{ id: 34,  category: "Eating & Drinking", arabic: "اللَّهُمَّ بَارِكْ لَنَا فِيمَا رَزَقْتَنَا وَقِنَا عَذَابَ النَّارِ", urdu: "اے اللہ! جو رزق تو نے ہمیں دیا اس میں برکت دے اور ہمیں آگ کے عذاب سے بچا۔", translit: "Allahumma barik lana fima razaqtana wa qina 'adhaban-nar" },
{ id: 35,  category: "Eating & Drinking", arabic: "الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنِي هَذَا وَرَزَقَنِيهِ مِنْ غَيْرِ حَوْلٍ مِنِّي وَلَا قُوَّةٍ", urdu: "شکر ہے اللہ کا جس نے مجھے یہ کھلایا اور بغیر میری طاقت و قوت کے مجھے یہ رزق دیا۔", translit: "Alhamdulillahil-ladhi at'amani hadha wa razaqanihi min ghayri hawlin minni wa la quwwa" },
{ id: 36,  category: "Eating & Drinking", arabic: "الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنِي وَسَقَانِي وَجَعَلَنِي مِنَ الْمُسْلِمِينَ", urdu: "شکر ہے اللہ کا جس نے مجھے کھلایا، پلایا اور مجھے مسلمانوں میں سے بنایا۔", translit: "Alhamdulillahil-ladhi at'amani wa saqani wa ja'alanii minal-muslimin" },
{ id: 37,  category: "Eating & Drinking", arabic: "اللَّهُمَّ بَارِكْ لَنَا فِيهِ وَأَطْعِمْنَا خَيْرًا مِنْهُ", urdu: "اے اللہ! اس (دودھ) میں برکت عطا فرما اور ہمیں اس سے بہتر کھلا۔", translit: "Allahumma barik lana fihi wa at'imna khayran minhu" },
{ id: 38,  category: "Eating & Drinking", arabic: "الْحَمْدُ لِلَّهِ كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ، غَيْرَ مَكْفِيٍّ وَلَا مُوَدَّعٍ وَلَا مُسْتَغْنًى عَنْهُ رَبَّنَا", urdu: "بہت زیادہ، پاکیزہ اور بابرکت حمد اللہ کے لیے ہے، ایسی حمد جو کافی ہے، جو الوداع نہیں ہوتی اور جس سے ہمارا رب بے نیاز نہیں ہوتا۔", translit: "Alhamdu lillahi kathiran tayyiban mubarakan fihi, ghayra makfiyyin wa la muwadda'in wa la mustaghniyan 'anhu rabbuna" },
{ id: 39,  category: "Eating & Drinking", arabic: "بِسْمِ اللَّهِ أَوَّلَهُ وَآخِرَهُ", urdu: "اللہ کے نام سے اس کے شروع میں اور آخر میں (کھانے کے درمیان یاد آئے تو)۔", translit: "Bismillahi awwalahu wa akhirahu" },
{ id: 40,  category: "Eating & Drinking", arabic: "أَفْطَرَ عِنْدَكُمُ الصَّائِمُونَ، وَأَكَلَ طَعَامَكُمُ الْأَبْرَارُ، وَصَلَّتْ عَلَيْكُمُ الْمَلَائِكَةُ", urdu: "تمہارے ہاں روزہ دار افطار کریں، نیک لوگ تمہارا کھانا کھائیں اور فرشتے تم پر درود بھیجیں (کسی کے ہاں افطار کرنے والا پڑھے)۔", translit: "Aftara 'indakumus-sa'imun, wa akala ta'amakumul-abrar, wa sallat 'alaykumul-mala'ikah" },
{ id: 41,  category: "Eating & Drinking", arabic: "اللَّهُمَّ بَارِكْ لَهُمْ فِيمَا رَزَقْتَهُمْ، وَاغْفِرْ لَهُمْ وَارْحَمْهُمْ", urdu: "اے اللہ! جو کچھ تو نے انہیں دیا اس میں برکت دے، انہیں معاف فرما اور ان پر رحم فرما (میزبان کے لیے دعا)۔", translit: "Allahumma barik lahum fima razaqtahum, waghfir lahum warhamhum" },

/* ---------- HOME & ENTERING ---------- */
{ id: 42,  category: "Home & Entering", arabic: "بِسْمِ اللَّهِ وَلَجْنَا، وَبِسْمِ اللَّهِ خَرَجْنَا، وَعَلَى اللَّهِ رَبِّنَا تَوَكَّلْنَا", urdu: "اللہ کے نام سے ہم داخل ہوئے، اللہ کے نام سے ہم نکلے اور اپنے رب اللہ پر بھروسہ کیا۔", translit: "Bismillahi walajna, wa bismillahi kharajna, wa 'alallahi rabbina tawakkalna" },
{ id: 43,  category: "Home & Entering", arabic: "اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَ الْمَوْلِجِ وَخَيْرَ الْمَخْرَجِ، بِسْمِ اللَّهِ وَلَجْنَا وَبِسْمِ اللَّهِ خَرَجْنَا وَعَلَى اللَّهِ تَوَكَّلْنَا", urdu: "اے اللہ! میں تجھ سے بہتر داخلے اور بہتر نکلنے کا سوال کرتا ہوں، اللہ کے نام سے داخل ہوئے، اللہ کے نام سے نکلے اور اللہ پر بھروسہ کیا۔", translit: "Allahumma inni as'aluka khayral-mawlaji wa khayral-makhraji, bismillahi walajna wa bismillahi kharajna wa 'alallahi tawakkalna" },
{ id: 44,  category: "Home & Entering", arabic: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ أَنْ أَضِلَّ أَوْ أُضَلَّ، أَوْ أَزِلَّ أَوْ أُزَلَّ، أَوْ أَظْلِمَ أَوْ أُظْلَمَ، أَوْ أَجْهَلَ أَوْ يُجْهَلَ عَلَيَّ", urdu: "اے اللہ! میں تیری پناہ مانگتا ہوں گمراہ ہونے یا گمراہ کرنے، پھسلنے یا پھسلانے، ظلم کرنے یا ظلم ہونے اور جہالت یا جہالت سے دوچار ہونے سے۔", translit: "Allahumma inni a'udhu bika an adilla aw udalla, aw azilla aw uzalla, aw azlima aw uzlama, aw ajhala aw yujhala 'alayya" },
{ id: 45,  category: "Home & Entering", arabic: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْخُبُثِ وَالْخَبَائِثِ", urdu: "اے اللہ! میں بیت الخلاء میں داخل ہوتے وقت مرد و عورت شیاطین سے تیری پناہ مانگتا ہوں۔", translit: "Allahumma inni a'udhu bika minal-khubuthi wal-khaba'ith" },
{ id: 46,  category: "Home & Entering", arabic: "غُفْرَانَكَ", urdu: "اے اللہ! میں تیری بخشش چاہتا ہوں (بیت الخلاء سے نکلتے وقت)۔", translit: "Ghufranak" },
{ id: 47,  category: "Home & Entering", arabic: "رَبَّنَا أَنْزِلْنَا مُنْزَلًا مُبَارَكًا وَأَنْتَ خَيْرُ الْمُنْزِلِينَ", urdu: "اے ہمارے رب! ہمیں بابرکت منزل میں اتار، اور تو ہی بہترین اتارنے والا ہے۔", translit: "Rabbana anzilna munzalan mubarakan wa anta khayrul-munzilin" },
{ id: 48,  category: "Home & Entering", arabic: "أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ", urdu: "میں اللہ کے مکمل کلمات کے ذریعے اس کی مخلوق کے شر سے پناہ مانگتا ہوں۔", translit: "A'udhu bikalimatillahit-tammati min sharri ma khalaq" },
{ id: 49,  category: "Home & Entering", arabic: "آيِبُونَ تَائِبُونَ عَابِدُونَ لِرَبِّنَا حَامِدُونَ", urdu: "ہم واپس آ گئے، توبہ کرنے والے، عبادت کرنے والے اور اپنے رب کی حمد کرنے والے (سفر سے واپسی پر)۔", translit: "Ayibuna, ta'ibuna, 'abiduna, lirabbina hamidun" },

/* ---------- TRAVEL ---------- */
{ id: 50,  category: "Travel", arabic: "سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ، وَإِنَّا إِلَى رَبِّنَا لَمُنْقَلِبُونَ", urdu: "پاک ہے وہ اللہ جس نے یہ (سواری) ہمارے لیے مسخر کی، ہم اس کی طاقت نہ رکھتے تھے، اور ہم اپنے رب ہی کی طرف لوٹنے والے ہیں۔", translit: "Subhanal-ladhi sakhkhara lana hadha wa ma kunna lahu muqrinin, wa inna ila rabbina lamunqalibun" },
{ id: 51,  category: "Travel", arabic: "اللَّهُمَّ هَوِّنْ عَلَيْنَا سَفَرَنَا هَذَا، وَاطْوِ عَنَّا بُعْدَهُ", urdu: "اے اللہ! ہمارا یہ سفر آسان فرما اور اس کی دوری ہم پر کم کر دے۔", translit: "Allahumma hawwin 'alayna safarana hadha, wa-twi 'anna bu'dahu" },
{ id: 52,  category: "Travel", arabic: "اللَّهُمَّ أَنْتَ الصَّاحِبُ فِي السَّفَرِ، وَالْخَلِيفَةُ فِي الْأَهْلِ", urdu: "اے اللہ! تو سفر میں ساتھی ہے اور گھر والوں میں جانشین ہے۔", translit: "Allahumma antas-sahibu fis-safar, wal-khalifatu fil-ahl" },
{ id: 53,  category: "Travel", arabic: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ وَعْثَاءِ السَّفَرِ، وَكَآبَةِ الْمُنْقَلَبِ، وَسُوءِ الْمَنْظَرِ فِي الْمَالِ وَالْأَهْلِ", urdu: "اے اللہ! میں سفر کی تکلیف، واپسی کے رنج اور مال و اہل میں برے انجام سے تیری پناہ مانگتا ہوں۔", translit: "Allahumma inni a'udhu bika min wa'tha'is-safar, wa ka'abatil-munqalab, wa su'il-manzar fil-mali wal-ahl" },
{ id: 54,  category: "Travel", arabic: "بِسْمِ اللَّهِ مَجْرَاهَا وَمُرْسَاهَا إِنَّ رَبِّي لَغَفُورٌ رَحِيمٌ", urdu: "اللہ کے نام سے اس کا چلنا اور ٹھہرنا ہے، میرا رب یقیناً بخشنے والا مہربان ہے۔", translit: "Bismillahi majraha wa mursaha inna rabbi laghafurur-rahim" },
{ id: 55,  category: "Travel", arabic: "اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ، سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ", urdu: "اللہ سب سے بڑا ہے، اللہ سب سے بڑا ہے، اللہ سب سے بڑا ہے، پاک ہے وہ اللہ جس نے یہ ہمارے لیے مسخر کیا۔", translit: "Allahu akbar, Allahu akbar, Allahu akbar, subhanal-ladhi sakhkhara lana hadha wa ma kunna lahu muqrinin" },
{ id: 56,  category: "Travel", arabic: "اللَّهُمَّ رَبَّ السَّمَاوَاتِ السَّبْعِ وَمَا أَظْلَلْنَ، وَرَبَّ الْأَرَضِينَ السَّبْعِ وَمَا أَقْلَلْنَ، وَرَبَّ الشَّيَاطِينِ وَمَا أَضْلَلْنَ، أَعُوذُ بِكَ مِنْ شَرِّ خَلْقِكَ كُلِّهِمْ", urdu: "اے اللہ! ساتوں آسمانوں کا رب جنہوں نے سایہ کیا، ساتوں زمینوں کا رب جنہیں اٹھایا، شیاطین کا رب جنہیں گمراہی دی، میں تیری پوری مخلوق کے شر سے پناہ مانگتا ہوں۔", translit: "Allahumma rabbas-samawatis-sab'i wa ma azlalna, wa rabbal-aradinas-sab'i wa ma aqlalna, wa rabbash-shayatini wa ma adlalna, a'udhu bika min sharri khalqika kullihim" },
{ id: 57,  category: "Travel", arabic: "أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ", urdu: "میں اللہ کے مکمل کلمات کے ذریعے اس کی مخلوق کے شر سے پناہ مانگتا ہوں (کسی جگہ قیام پر)۔", translit: "A'udhu bikalimatillahit-tammati min sharri ma khalaq" },
{ id: 58,  category: "Travel", arabic: "اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَ هَذِهِ الْقَرْيَةِ وَخَيْرَ أَهْلِهَا وَخَيْرَ مَا فِيهَا", urdu: "اے اللہ! میں تجھ سے اس بستی کی بھلائی، اس کے رہنے والوں کی بھلائی اور اس میں جو کچھ ہے اس کی بھلائی کا سوال کرتا ہوں۔", translit: "Allahumma inni as'aluka khayra hadhihil-qaryati wa khayra ahliha wa khayra ma fiha" },
{ id: 59,  category: "Travel", arabic: "الْحَمْدُ لِلَّهِ الَّذِي هَدَانَا لِهَذَا وَمَا كُنَّا لِنَهْتَدِيَ لَوْلَا أَنْ هَدَانَا اللَّهُ", urdu: "شکر ہے اللہ کا جس نے ہمیں یہ راستہ دکھایا، ہم خود ہدایت نہ پاتے اگر اللہ ہمیں ہدایت نہ دیتا۔", translit: "Alhamdu lillahil-ladhi hadana lihadha wa ma kunna linahtadiya lawla an hadanallahu" },

/* ---------- MORNING & EVENING ---------- */
{ id: 60,  category: "Morning & Evening", arabic: "أَصْبَحْنَا عَلَى فِطْرَةِ الْإِسْلَامِ، وَعَلَى كَلِمَةِ الْإِخْلَاصِ، وَعَلَى دِينِ نَبِيِّنَا مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَعَلَى مِلَّةِ أَبِينَا إِبْرَاهِيمَ حَنِيفًا مُسْلِمًا وَمَا كَانَ مِنَ الْمُشْرِكِينَ", urdu: "ہم نے فطرتِ اسلام، کلمہ اخلاص، ہمارے نبی محمد صلی اللہ علیہ وسلم کے دین اور ہمارے باپ ابراہیم کی ملت پر صبح کی جو حنیف و مسلمان تھے اور مشرکوں میں سے نہ تھے۔", translit: "Asbahna 'ala fitratil-Islam, wa 'ala kalimatil-ikhlas, wa 'ala dini nabiyyina Muhammadin, wa 'ala millati abina Ibrahima hanifan musliman wa ma kana minal-mushrikin" },
{ id: 61,  category: "Morning & Evening", arabic: "اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ", urdu: "اے اللہ! میں تجھ سے دنیا و آخرت میں معافی اور عافیت کا سوال کرتا ہوں۔", translit: "Allahumma inni as'alukal-'afwa wal-'afiyah fid-dunya wal-akhirah" },
{ id: 62,  category: "Morning & Evening", arabic: "حَسْبِيَ اللَّهُ لَا إِلَهَ إِلَّا هُوَ عَلَيْهِ تَوَكَّلْتُ وَهُوَ رَبُّ الْعَرْشِ الْعَظِيمِ", urdu: "میرے لیے اللہ کافی ہے، اس کے سوا کوئی معبود نہیں، اسی پر بھروسہ کیا اور وہی عظیم عرش کا رب ہے۔", translit: "Hasbiyallahu la ilaha illa huwa 'alayhi tawakkaltu wa huwa rabbul-'arshil-'azim" },
{ id: 63,  category: "Morning & Evening", arabic: "بِسْمِ اللَّهِ الَّذِي لَا يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الْأَرْضِ وَلَا فِي السَّمَاءِ وَهُوَ السَّمِيعُ الْعَلِيمُ", urdu: "اللہ کے نام سے جس کے نام کے ساتھ زمین و آسمان کی کوئی چیز نقصان نہیں پہنچا سکتی، اور وہ سننے والا جاننے والا ہے۔", translit: "Bismillahil-ladhi la yadurru ma'asmihi shay'un fil-ardi wa la fis-sama'i wa huwas-sami'ul-'alim" },
{ id: 64,  category: "Morning & Evening", arabic: "رَبِّ أَعُوذُ بِكَ مِنْ هَمَزَاتِ الشَّيَاطِينِ، وَأَعُوذُ بِكَ رَبِّ أَنْ يَحْضُرُونِ", urdu: "اے میرے رب! میں شیاطین کے وسوسوں سے تیری پناہ مانگتا ہوں اور اس سے بھی کہ وہ میرے پاس آئیں۔", translit: "Rabbi a'udhu bika min hamazatish-shayatin, wa a'udhu bika rabbi an yahdurun" },
{ id: 65,  category: "Morning & Evening", arabic: "اللَّهُمَّ عَالِمَ الْغَيْبِ وَالشَّهَادَةِ فَاطِرَ السَّمَاوَاتِ وَالْأَرْضِ، رَبَّ كُلِّ شَيْءٍ وَمَلِيكَهُ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَعُوذُ بِكَ مِنْ شَرِّ نَفْسِي وَمِنْ شَرِّ الشَّيْطَانِ وَشِرْكِهِ", urdu: "اے اللہ! چھپے کھلے کا جاننے والے، آسمانوں و زمین کے پیدا کرنے والے، ہر چیز کے رب اور مالک! میں گواہی دیتا ہوں کہ تیرے سوا کوئی معبود نہیں، میں اپنے نفس کے شر اور شیطان و اس کے شرک کے شر سے تیری پناہ مانگتا ہوں۔", translit: "Allahumma 'alimal-ghaybi wash-shahadati fatiras-samawati wal-ardi, rabba kulli shay'in wa malikah, ash-hadu an la ilaha illa anta, a'udhu bika min sharri nafsi wa min sharrish-shaytani wa shirkih" },
{ id: 66,  category: "Morning & Evening", arabic: "سُبْحَانَ اللَّهِ وَبِحَمْدِهِ عَدَدَ خَلْقِهِ، وَرِضَا نَفْسِهِ، وَزِنَةَ عَرْشِهِ، وَمِدَادَ كَلِمَاتِهِ", urdu: "اللہ کی پاکی اس کی حمد کے ساتھ، جتنی اس کی مخلوق ہے، جتنی اس کی رضا ہے، جتنا اس کا عرش ہے اور جتنے اس کے کلمات ہیں۔", translit: "Subhanallahi wa bihamdihi 'adada khalqihi, wa rida nafsihi, wa zinata 'arshihi, wa midada kalimatih" },
{ id: 67,  category: "Morning & Evening", arabic: "أَمْسَيْنَا وَأَمْسَى الْمُلْكُ لِلَّهِ، وَالْحَمْدُ لِلَّهِ، لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ", urdu: "ہم نے شام کی اور شام کی بادشاہی اللہ ہی کے لیے ہے، تمام حمد اللہ کے لیے، اللہ کے سوا کوئی معبود نہیں، بادشاہت اور حمد اسی کے لیے ہے، وہ ہر چیز پر قادر ہے۔", translit: "Amsayna wa amsal-mulku lillah, wal-hamdu lillah, la ilaha illallahu wahdahu la sharika lahu, lahul-mulku wa lahul-hamdu wa huwa 'ala kulli shay'in qadir" },
{ id: 68,  category: "Morning & Evening", arabic: "رَبَّنَا مَا خَلَقْتَ هَذَا بَاطِلًا سُبْحَانَكَ فَقِنَا عَذَابَ النَّارِ", urdu: "اے ہمارے رب! تو نے یہ سب بیکار نہیں بنایا، پاک ہے تو، ہمیں آگ کے عذاب سے بچا۔", translit: "Rabbana ma khalaqta hadha batilan subhanaka faqina 'adhaban-nar" },
{ id: 69,  category: "Morning & Evening", arabic: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَالْعَجْزِ وَالْكَسَلِ، وَالْبُخْلِ وَالْجُبْنِ، وَضَلَعِ الدَّيْنِ وَغَلَبَةِ الرِّجَالِ", urdu: "اے اللہ! میں غم، پریشانی، عجز، سستی، بخل، بزدلی، قرض کے بوجھ اور لوگوں کے غلبہ سے تیری پناہ مانگتا ہوں۔", translit: "Allahumma inni a'udhu bika minal-hammi wal-hazan, wal-'ajzi wal-kasal, wal-bukhli wal-jubn, wa dala'id-dayni wa ghalabatir-rijal" },
{ id: 70,  category: "Morning & Evening", arabic: "يَا حَيُّ يَا قَيُّومُ بِرَحْمَتِكَ أَسْتَغِيثُ، أَصْلِحْ لِي شَأْنِي كُلَّهُ وَلَا تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ", urdu: "اے زندہ و قائم رب! تیری رحمت سے فریاد ہے، میرا سارا معاملہ درست فرما اور مجھے پل بھر کے لیے بھی میرے نفس کے حوالے نہ کر۔", translit: "Ya Hayyu ya Qayyumu birahmatika astaghith, aslih li sha'ni kullahu wa la takilni ila nafsi tarfata 'ayn" },
{ id: 71,  category: "Morning & Evening", arabic: "أَسْتَغْفِرُ اللَّهَ وَأَتُوبُ إِلَيْهِ", urdu: "اللہ سے معافی مانگتا ہوں اور اسی کی طرف توبہ کرتا ہوں (سو مرتبہ)۔", translit: "Astaghfirullaha wa atubu ilayh" },
{ id: 72,  category: "Morning & Evening", arabic: "سُبْحَانَ اللَّهِ وَبِحَمْدِهِ", urdu: "اللہ کی پاکی بیان کرتا ہوں اس کی حمد کے ساتھ (سو مرتبہ — گناہ معاف ہوتے ہیں چاہے سمندر کے جھاگ برابر ہوں)۔", translit: "Subhanallahi wa bihamdih" },
{ id: 73,  category: "Morning & Evening", arabic: "لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ", urdu: "اللہ کے بغیر نہ طاقت ہے نہ قوت، یہ جنت کے خزانوں میں سے ایک خزانہ ہے۔", translit: "La hawla wa la quwwata illa billah" },
{ id: 74,  category: "Morning & Evening", arabic: "رَضِيتُ بِاللَّهِ رَبًّا، وَبِالْإِسْلَامِ دِينًا، وَبِمُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَبِيًّا", urdu: "میں اللہ کو رب، اسلام کو دین اور محمد صلی اللہ علیہ وسلم کو نبی مان کر راضی ہوں (تین مرتبہ)۔", translit: "Raditu billahi rabban, wa bil-Islami dinan, wa bi-Muhammadin sallallahu 'alayhi wa sallama nabiyya" },
{ id: 75,  category: "Morning & Evening", arabic: "قُلْ هُوَ اللَّهُ أَحَدٌ، قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ، قُلْ أَعُوذُ بِرَبِّ النَّاسِ (ثَلَاثَ مَرَّاتٍ)", urdu: "سورۃ الاخلاص، فلق اور الناس تین تین مرتبہ — صبح و شام تین بار پڑھنے والے کے لیے ہر چیز کافی ہو جاتی ہے۔", translit: "Qul huwa Allahu ahad, Qul a'udhu bi rabbil-falaq, Qul a'udhu bi rabbin-nas (3x)" },
{ id: 76,  category: "Morning & Evening", arabic: "اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ عَلَيْكَ تَوَكَّلْتُ وَأَنْتَ رَبُّ الْعَرْشِ الْعَظِيمِ", urdu: "اے اللہ! تو میرا رب ہے، تیرے سوا کوئی معبود نہیں، تجھ پر بھروسہ کیا اور تو عظیم عرش کا رب ہے۔", translit: "Allahumma anta rabbi la ilaha illa anta 'alayka tawakkaltu wa anta rabbul-'arshil-'azim" },
{ id: 77,  category: "Morning & Evening", arabic: "اللَّهُمَّ مَا أَصْبَحَ بِي مِنْ نِعْمَةٍ فَمِنْكَ وَحْدَكَ لَا شَرِيكَ لَكَ، فَلَكَ الْحَمْدُ وَلَكَ الشُّكْرُ", urdu: "اے اللہ! جو نعمت بھی مجھ پر صبح ہوئی وہ صرف تیری طرف سے ہے، تیرا کوئی شریک نہیں، تیرے لیے حمد اور شکر ہے۔", translit: "Allahumma ma asbaha bi min ni'matin faminka wahdaka la sharika laka, falakal-hamdu wa lakash-shukr" },

/* ---------- KNOWLEDGE ---------- */
{ id: 78,  category: "Knowledge", arabic: "رَبِّ زِدْنِي عِلْمًا", urdu: "اے میرے رب! میرے علم میں اضافہ فرما۔", translit: "Rabbi zidni 'ilma" },
{ id: 79,  category: "Knowledge", arabic: "اللَّهُمَّ انْفَعْنِي بِمَا عَلَّمْتَنِي، وَعَلِّمْنِي مَا يَنْفَعُنِي، وَزِدْنِي عِلْمًا", urdu: "اے اللہ! جو علم تو نے مجھے دیا اس سے فائدہ عطا فرما، مجھے نفع بخش علم سکھا اور میرا علم بڑھا۔", translit: "Allahummanfa'ni bima 'allamtani, wa 'allimni ma yanfa'uni, wa zidni 'ilma" },
{ id: 80,  category: "Knowledge", arabic: "اللَّهُمَّ إِنِّي أَسْأَلُكَ عِلْمًا نَافِعًا، وَرِزْقًا طَيِّبًا، وَعَمَلًا مُتَقَبَّلًا", urdu: "اے اللہ! میں نافع علم، پاکیزہ رزق اور قبول شدہ عمل کا سوال کرتا ہوں۔", translit: "Allahumma inni as'aluka 'ilman nafi'an, wa rizqan tayyiban, wa 'amalan mutaqabbalan" },
{ id: 81,  category: "Knowledge", arabic: "اللَّهُمَّ عَلِّمْنِي مَا يَنْفَعُنِي، وَانْفَعْنِي بِمَا عَلَّمْتَنِي، وَزِدْنِي عِلْمًا، وَالْحَمْدُ لِلَّهِ عَلَى كُلِّ حَالٍ، وَأَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ", urdu: "اے اللہ! مجھے نفع بخش علم سکھا، سکھائے ہوئے سے نفع دے، علم بڑھا، ہر حال پر حمد اللہ کے لیے ہے، میں قبر کے عذاب سے پناہ مانگتا ہوں۔", translit: "Allahumma 'allimni ma yanfa'uni, wanfa'ni bima 'allamtani, wa zidni 'ilma, walhamdu lillahi 'ala kulli hal, wa a'udhu bika min 'adhabil-qabr" },
{ id: 82,  category: "Knowledge", arabic: "رَبِّ اشْرَحْ لِي صَدْرِي، وَيَسِّرْ لِي أَمْرِي، وَاحْلُلْ عُقْدَةً مِنْ لِسَانِي، يَفْقَهُوا قَوْلِي", urdu: "اے میرے رب! میرا سینہ کھول دے، میرا کام آسان کر دے اور میری زبان کی گرہ کھول دے تاکہ لوگ میری بات سمجھیں۔", translit: "Rabbishrah li sadri, wa yassir li amri, wah-lul 'uqdatan min lisani, yafqahu qawli" },
{ id: 83,  category: "Knowledge", arabic: "اللَّهُمَّ لَا سَهْلَ إِلَّا مَا جَعَلْتَهُ سَهْلًا، وَأَنْتَ تَجْعَلُ الْحَزْنَ إِذَا شِئْتَ سَهْلًا", urdu: "اے اللہ! آسان نہیں سوائے اس کے جسے تو نے آسان کیا، اور تو مشکل کو چاہے تو آسان کر دیتا ہے۔", translit: "Allahumma la sahla illa ma ja'altahu sahla, wa anta taj'alul-hazna idha shi'ta sahla" },
{ id: 84,  category: "Knowledge", arabic: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عِلْمٍ لَا يَنْفَعُ، وَمِنْ قَلْبٍ لَا يَخْشَعُ، وَمِنْ نَفْسٍ لَا تَشْبَعُ، وَمِنْ دُعَاءٍ لَا يُسْمَعُ", urdu: "اے اللہ! میں بے نفع علم، بے خشوع دل، نہ سیر ہونے والے نفس اور قبول نہ ہونے والی دعا سے تیری پناہ مانگتا ہوں۔", translit: "Allahumma inni a'udhu bika min 'ilmin la yanfa', wa min qalbin la yakhsha', wa min nafsin la tashba', wa min du'a'in la yusma'" },
{ id: 85,  category: "Knowledge", arabic: "اللَّهُمَّ اغْفِرْ لِي وَلِلْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ", urdu: "اے اللہ! مجھے اور تمام مومن مردوں اور عورتوں کو معاف فرما۔", translit: "Allahumma-ghfir li wa lil-mu'minina wal-mu'minat" },

/* ---------- REPENTANCE & FORGIVENESS ---------- */
{ id: 86,  category: "Repentance & Forgiveness", arabic: "أَسْتَغْفِرُ اللَّهَ", urdu: "اللہ سے معافی مانگتا ہوں۔", translit: "Astaghfirullah" },
{ id: 87,  category: "Repentance & Forgiveness", arabic: "أَسْتَغْفِرُ اللَّهَ وَأَتُوبُ إِلَيْهِ", urdu: "اللہ سے معافی مانگتا ہوں اور اسی کی طرف توبہ کرتا ہوں۔", translit: "Astaghfirullaha wa atubu ilayh" },
{ id: 88,  category: "Repentance & Forgiveness", arabic: "اللَّهُمَّ أَنْتَ السَّلَامُ وَمِنْكَ السَّلَامُ، تَبَارَكْتَ يَا ذَا الْجَلَالِ وَالْإِكْرَامِ", urdu: "اے اللہ! تو سلام ہے، سلامتی تجھ ہی سے ہے، بابرکت ہے تو اے جلال و کرم والے! (نماز کے بعد)۔", translit: "Allahumma antas-salam wa minkas-salam, tabarakta ya dhal-jalali wal-ikram" },
{ id: 89,  category: "Repentance & Forgiveness", arabic: "اللَّهُمَّ إِنِّي ظَلَمْتُ نَفْسِي ظُلْمًا كَثِيرًا، وَلَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ، فَاغْفِرْ لِي مَغْفِرَةً مِنْ عِنْدِكَ وَارْحَمْنِي، إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ", urdu: "اے اللہ! میں نے اپنے نفس پر بہت ظلم کیا اور گناہ صرف تو ہی معاف کرتا ہے، پس اپنی طرف سے مجھے بخش دے اور مجھ پر رحم فرما، بیشک تو ہی بخشنے والا مہربان ہے۔", translit: "Allahumma inni zalamtu nafsi zulman kathiran wa la yaghfirudh-dhunuba illa anta, faghfir li maghfiratan min 'indika warhamni, innaka antal-ghafurur-rahim" },
{ id: 90,  category: "Repentance & Forgiveness", arabic: "رَبَّنَا ظَلَمْنَا أَنْفُسَنَا وَإِنْ لَمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَكُونَنَّ مِنَ الْخَاسِرِينَ", urdu: "اے ہمارے رب! ہم نے اپنی جانوں پر ظلم کیا، اگر تو معاف اور رحم نہ کرے تو ہم یقیناً نقصان اٹھانے والوں میں ہوں گے۔", translit: "Rabbana zalamna anfusana wa in lam taghfir lana wa tarhamna lanakunanna minal-khasirin" },
{ id: 91,  category: "Repentance & Forgiveness", arabic: "رَبِّ اغْفِرْ لِي وَلِوَالِدَيَّ وَلِمَنْ دَخَلَ بَيْتِيَ مُؤْمِنًا وَلِلْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ", urdu: "اے میرے رب! مجھے، میرے والدین کو، جو بھی مومن میرے گھر آئے اور تمام مومن مردوں و عورتوں کو معاف فرما۔", translit: "Rabbighfir li wa liwalidayya wa liman dakhala baytiya mu'minan wa lil-mu'minina wal-mu'minat" },
{ id: 92,  category: "Repentance & Forgiveness", arabic: "اللَّهُمَّ اغْفِرْ لِي خَطِيئَتِي وَجَهْلِي وَإِسْرَافِي فِي أَمْرِي، وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي، اللَّهُمَّ اغْفِرْ لِي جِدِّي وَهَزْلِي وَخَطَئِي وَعَمْدِي وَكُلُّ ذَلِكَ عِنْدِي", urdu: "اے اللہ! میری خطا، جہالت، معاملات میں زیادتی اور جو کچھ تو مجھ سے زیادہ جانتا ہے سب معاف فرما، میری سنجیدہ و ہنسی باتوں اور بھول و عمدہ خطاؤں کو معاف فرما۔", translit: "Allahumma-ghfir li khati'ati wa jahli wa israfi fi amri, wa ma anta a'lamu bihi minni, Allahumma-ghfir li jiddi wa hazli wa khata'i wa 'amdi wa kullu dhalika 'indi" },
{ id: 93,  category: "Repentance & Forgiveness", arabic: "رَبَّنَا إِنَّنَا آمَنَّا فَاغْفِرْ لَنَا ذُنُوبَنَا وَقِنَا عَذَابَ النَّارِ", urdu: "اے ہمارے رب! ہم ایمان لائے ہیں، ہمارے گناہ معاف فرما اور ہمیں آگ کے عذاب سے بچا۔", translit: "Rabbana innana amanna faghfir lana dhunubana wa qina 'adhaban-nar" },
{ id: 94,  category: "Repentance & Forgiveness", arabic: "رَبَّنَا لَا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا، رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَا إِصْرًا كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِنْ قَبْلِنَا", urdu: "اے ہمارے رب! اگر ہم بھول جائیں یا غلطی کریں تو ہمیں نہ پکڑ، اور ہم پر ایسا بوجھ نہ ڈال جیسا تو نے ہم سے پہلوں پر ڈالا۔", translit: "Rabbana la tu'akhidhna in nasina aw akhta'na, rabbana wa la tahmil 'alayna isran kama hamaltahu 'alal-ladhina min qablina" },
{ id: 95,  category: "Repentance & Forgiveness", arabic: "رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِنْ لَدُنْكَ رَحْمَةً إِنَّكَ أَنْتَ الْوَهَّابُ", urdu: "اے ہمارے رب! ہدایت کے بعد ہمارے دلوں کو ٹیڑھا نہ کر اور اپنے پاس سے ہمیں رحمت عطا فرما، بیشک تو ہی عطا کرنے والا ہے۔", translit: "Rabbana la tuzigh qulubana ba'da idh hadaytana wa hab lana min ladunka rahmah, innaka antal-wahhab" },
{ id: 96,  category: "Repentance & Forgiveness", arabic: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ أَنْ أُشْرِكَ بِكَ وَأَنَا أَعْلَمُ، وَأَسْتَغْفِرُكَ لِمَا لَا أَعْلَمُ", urdu: "اے اللہ! میں جان بوجھ کر شرک کرنے سے تیری پناہ مانگتا ہوں اور اپنی لاعلمی کی خطا پر معافی مانگتا ہوں۔", translit: "Allahumma inni a'udhu bika an ushrika bika wa ana a'lam, wa astaghfiruka lima la a'lam" },
{ id: 97,  category: "Repentance & Forgiveness", arabic: "سُبْحَانَكَ إِنِّي كُنْتُ مِنَ الظَّالِمِينَ", urdu: "پاک ہے تو، میں ظالموں میں سے تھا۔", translit: "Subhanaka inni kuntu minaz-zalimin" },
{ id: 98,  category: "Repentance & Forgiveness", arabic: "رَبِّ اغْفِرْ لِي وَتُبْ عَلَيَّ إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيمُ", urdu: "اے میرے رب! مجھے معاف فرما اور میری توبہ قبول فرما، بیشک تو ہی توبہ قبول کرنے والا مہربان ہے۔", translit: "Rabbighfir li wa tub 'alayya innaka antat-tawwabur-rahim" },
{ id: 99,  category: "Repentance & Forgiveness", arabic: "اللَّهُمَّ اغْفِرْ لِي مَا قَدَّمْتُ وَمَا أَخَّرْتُ", urdu: "اے اللہ! میرے اگلے پچھلے گناہ معاف فرما۔", translit: "Allahumma-ghfir li ma qaddamtu wa ma akkhartu" },

/* ---------- ANXIETY & DISTRESS ---------- */
{ id: 100, category: "Anxiety & Distress", arabic: "لَا إِلَهَ إِلَّا اللَّهُ الْعَظِيمُ الْحَلِيمُ، لَا إِلَهَ إِلَّا اللَّهُ رَبُّ الْعَرْشِ الْعَظِيمِ، لَا إِلَهَ إِلَّا اللَّهُ رَبُّ السَّمَاوَاتِ وَرَبُّ الْأَرْضِ وَرَبُّ الْعَرْشِ الْكَرِيمِ", urdu: "اللہ کے سوا کوئی معبود نہیں جو عظیم اور بردبار ہے، اللہ کے سوا کوئی معبود نہیں جو عرش عظیم کا رب ہے، اللہ کے سوا کوئی معبود نہیں جو آسمانوں، زمین اور عرش کریم کا رب ہے۔", translit: "La ilaha illallahul-'azimul-halim, la ilaha illallahu rabbul-'arshil-'azim, la ilaha illallahu rabbus-samawati wa rabbul-ardi wa rabbul-'arshil-karim" },
{ id: 101, category: "Anxiety & Distress", arabic: "اللَّهُمَّ رَحْمَتَكَ أَرْجُو، فَلَا تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ، وَأَصْلِحْ لِي شَأْنِي كُلَّهُ، لَا إِلَهَ إِلَّا أَنْتَ", urdu: "اے اللہ! تیری رحمت کی امید ہے، مجھے پل بھر اپنے نفس کے حوالے نہ کر، میرا سارا معاملہ درست فرما، تیرے سوا کوئی معبود نہیں۔", translit: "Allahumma rahmataka arju, fa la takilni ila nafsi tarfata 'ayn, wa aslih li sha'ni kullahu, la ilaha illa anta" },
{ id: 102, category: "Anxiety & Distress", arabic: "لَا إِلَهَ إِلَّا أَنْتَ سُبْحَانَكَ إِنِّي كُنْتُ مِنَ الظَّالِمِينَ", urdu: "تیرے سوا کوئی معبود نہیں، پاک ہے تو، میں ظالموں میں سے تھا۔", translit: "La ilaha illa anta subhanaka inni kuntu minaz-zalimin" },
{ id: 103, category: "Anxiety & Distress", arabic: "حَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيلُ", urdu: "ہمارے لیے اللہ کافی ہے اور وہ بہترین کارساز ہے۔", translit: "Hasbunallahu wa ni'mal-wakil" },
{ id: 104, category: "Anxiety & Distress", arabic: "رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ", urdu: "اے ہمارے رب! ہمیں دنیا میں بھلائی اور آخرت میں بھلائی عطا فرما اور آگ کے عذاب سے بچا۔", translit: "Rabbana atina fid-dunya hasanatan wa fil-akhirati hasanatan wa qina 'adhaban-nar" },
{ id: 105, category: "Anxiety & Distress", arabic: "يَا مُقَلِّبَ الْقُلُوبِ ثَبِّتْ قَلْبِي عَلَى دِينِكَ", urdu: "اے دلوں کے پلٹنے والے! میرے دل کو اپنے دین پر ثابت رکھ۔", translit: "Ya muqallibal-qulub, thabbit qalbi 'ala dinik" },
{ id: 106, category: "Anxiety & Distress", arabic: "اللَّهُمَّ إِنَّا نَجْعَلُكَ فِي نُحُورِهِمْ، وَنَعُوذُ بِكَ مِنْ شُرُورِهِمْ", urdu: "اے اللہ! ہم تجھے ان کے سامنے کرتے ہیں (ان سے تحفظ تیرے ذریعے مانگتے ہیں) اور ان کے شر سے تیری پناہ مانگتے ہیں۔", translit: "Allahumma inna naj'aluka fi nuhurihim, wa na'udhu bika min shururihim" },
{ id: 107, category: "Anxiety & Distress", arabic: "اللَّهُمَّ اكْفِنِي بِحَلَالِكَ عَنْ حَرَامِكَ، وَأَغْنِنِي بِفَضْلِكَ عَمَّنْ سِوَاكَ", urdu: "اے اللہ! مجھے حلال سے حرام سے بچنے کی کفایت عطا فرما اور اپنے فضل سے تیرے سوا ہر ایک سے بے نیاز فرما۔", translit: "Allahumma-kfini bihalalika 'an haramik, wa aghnini bifadlika 'amman siwak" },
{ id: 108, category: "Anxiety & Distress", arabic: "رَبَّنَا أَفْرِغْ عَلَيْنَا صَبْرًا وَثَبِّتْ أَقْدَامَنَا وَانْصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ", urdu: "اے ہمارے رب! ہم پر صبر انڈیل دے، ہمارے قدم جما دے اور کافر قوم پر ہمیں نصرت عطا فرما۔", translit: "Rabbana afrigh 'alayna sabran wa thabbit aqdamana wansurna 'alal-qawmil-kafirin" },
{ id: 109, category: "Anxiety & Distress", arabic: "رَبَّنَا أَفْرِغْ عَلَيْنَا صَبْرًا وَتَوَفَّنَا مُسْلِمِينَ", urdu: "اے ہمارے رب! ہم پر صبر نازل فرما اور ہمیں مسلمان کی حالت میں وفات دے۔", translit: "Rabbana afrigh 'alayna sabran wa tawaffana muslimin" },
{ id: 110, category: "Anxiety & Distress", arabic: "إِنِّي مَسَّنِيَ الضُّرُّ وَأَنْتَ أَرْحَمُ الرَّاحِمِينَ", urdu: "مجھے تکلیف نے چھو لیا ہے اور تو سب سے بڑھ کر رحم کرنے والا ہے۔", translit: "Inni massaniyad-durru wa anta arhamur-rahimin" },
{ id: 111, category: "Anxiety & Distress", arabic: "اللَّهُمَّ إِنِّي أَسْأَلُكَ مُوجِبَاتِ رَحْمَتِكَ، وَعَزَائِمَ مَغْفِرَتِكَ، وَالسَّلَامَةَ مِنْ كُلِّ إِثْمٍ، وَالْغَنِيمَةَ مِنْ كُلِّ بِرٍّ، وَالْفَوْزَ بِالْجَنَّةِ، وَالنَّجَاةَ مِنَ النَّارِ", urdu: "اے اللہ! میں تجھ سے تیری رحمت کے اسباب، مغفرت کے عزائم، ہر گناہ سے سلامتی، ہر نیکی سے غنیمت، جنت سے کامیابی اور آگ سے نجات کا سوال کرتا ہوں۔", translit: "Allahumma inni as'aluka mujibati rahmatik, wa 'aza'ima maghfiratik, was-salamata min kulli ithm, wal-ghanimata min kulli birr, wal-fawza bil-jannah, wan-najata minan-nar" },
{ id: 112, category: "Anxiety & Distress", arabic: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْكُفْرِ وَالْفَقْرِ", urdu: "اے اللہ! میں کفر اور فقر سے تیری پناہ مانگتا ہوں۔", translit: "Allahumma inni a'udhu bika minal-kufri wal-faqri" },

/* ---------- PARENTS & FAMILY ---------- */
{ id: 113, category: "Parents & Family", arabic: "رَبِّ ارْحَمْهُمَا كَمَا رَبَّيَانِي صَغِيرًا", urdu: "اے میرے رب! ان دونوں پر رحم فرما جیسے انہوں نے بچپن میں مجھے پالا۔", translit: "Rabbirhamhuma kama rabbayani saghira" },
{ id: 114, category: "Parents & Family", arabic: "رَبِّ اغْفِرْ لِي وَلِوَالِدَيَّ", urdu: "اے میرے رب! مجھے اور میرے والدین کو معاف فرما۔", translit: "Rabbighfir li wa liwalidayya" },
{ id: 115, category: "Parents & Family", arabic: "رَبَّنَا هَبْ لَنَا مِنْ أَزْوَاجِنَا وَذُرِّيَّاتِنَا قُرَّةَ أَعْيُنٍ وَاجْعَلْنَا لِلْمُتَّقِينَ إِمَامًا", urdu: "اے ہمارے رب! ہمیں اپنی بیویوں اور اولاد سے آنکھوں کی ٹھنڈک عطا فرما اور ہمیں پرہیزگاروں کا امام بنا۔", translit: "Rabbana hab lana min azwajina wa dhurriyyatina qurrata a'yun, waj'alna lil-muttaqina imama" },
{ id: 116, category: "Parents & Family", arabic: "رَبَّنَا هَبْ لَنَا مِنْ لَدُنْكَ رَحْمَةً وَهَيِّئْ لَنَا مِنْ أَمْرِنَا رَشَدًا", urdu: "اے ہمارے رب! اپنے پاس سے ہمیں رحمت عطا فرما اور ہمارے معاملے میں راست بازی مہیا فرما۔", translit: "Rabbana hab lana min ladunka rahmah wa hayyi' lana min amrina rashada" },
{ id: 117, category: "Parents & Family", arabic: "رَبِّ أَوْزِعْنِي أَنْ أَشْكُرَ نِعْمَتَكَ الَّتِي أَنْعَمْتَ عَلَيَّ وَعَلَى وَالِدَيَّ، وَأَنْ أَعْمَلَ صَالِحًا تَرْضَاهُ، وَأَصْلِحْ لِي فِي ذُرِّيَّتِي، إِنِّي تُبْتُ إِلَيْكَ وَإِنِّي مِنَ الْمُسْلِمِينَ", urdu: "اے میرے رب! مجھے توفیق دے کہ میں تیری نعمت کا شکر ادا کروں جو تو نے مجھے اور میرے والدین کو دی، نیک عمل کروں جو تو پسند کرے، میری اولاد میں اصلاح فرما، میں تیری طرف توبہ کرتا ہوں اور مسلمانوں میں سے ہوں۔", translit: "Rabbi awzi'ni an ashkura ni'matakal-lati an'amta 'alayya wa 'ala walidayya, wa an a'mala salihan tardah, wa aslih li fi dhurriyyati, inni tubtu ilayka wa inni minal-muslimin" },
{ id: 118, category: "Parents & Family", arabic: "رَبَّنَا وَاجْعَلْنَا مُسْلِمَيْنِ لَكَ وَمِنْ ذُرِّيَّتِنَا أُمَّةً مُسْلِمَةً لَكَ", urdu: "اے ہمارے رب! ہمیں اپنا فرمانبردار بنا اور ہماری اولاد میں سے بھی ایک فرمانبردار امت بنا۔", translit: "Rabbana waj'alna muslimayni laka wa min dhurriyyatina ummatan muslimatan laka" },
{ id: 119, category: "Parents & Family", arabic: "رَبِّ أَعِنِّي وَلَا تُعِنْ عَلَيَّ، وَانْصُرْنِي وَلَا تَنْصُرْ عَلَيَّ، وَامْكُرْ لِي وَلَا تَمْكُرْ عَلَيَّ", urdu: "اے میرے رب! میری مدد فرما میرے خلاف نہ، مجھ پر نصرت دے میرے خلاف نہ، میری تدبیر فرما میرے خلاف تدبیر نہ کر۔", translit: "Rabbi a'inni wa la tu'in 'alayya, wansurni wa la tansur 'alayya, wamkur li wa la tamkur 'alayya" },
{ id: 120, category: "Parents & Family", arabic: "رَبِّ إِنِّي لِمَا أَنْزَلْتَ إِلَيَّ مِنْ خَيْرٍ فَقِيرٌ", urdu: "اے میرے رب! جو خیر بھی تو مجھ پر نازل کرے، میں اس کا محتاج ہوں۔", translit: "Rabbi inni lima anzalta ilayya min khayrin faqir" },
{ id: 121, category: "Parents & Family", arabic: "رَبَّنَا تَقَبَّلْ مِنَّا إِنَّكَ أَنْتَ السَّمِيعُ الْعَلِيمُ", urdu: "اے ہمارے رب! ہم سے (اعمال) قبول فرما، بیشک تو ہی سننے والا جاننے والا ہے۔", translit: "Rabbana taqabbal minna innaka antas-sami'ul-'alim" },
{ id: 122, category: "Parents & Family", arabic: "اللَّهُمَّ أَلِّفْ بَيْنَ قُلُوبِنَا وَأَصْلِحْ ذَاتَ بَيْنِنَا", urdu: "اے اللہ! ہمارے دلوں کے درمیان محبت ڈال دے اور ہماری آپس کی صلح فرما دے۔", translit: "Allahumma allif bayna qulubina wa aslih dhata baynina" },

/* ---------- RIZQ & SUSTENANCE ---------- */
{ id: 123, category: "Rizq & Sustenance", arabic: "اللَّهُمَّ أَغْنِنِي بِحَلَالِكَ عَنْ حَرَامِكَ، وَبِفَضْلِكَ عَمَّنْ سِوَاكَ", urdu: "اے اللہ! مجھے حلال سے حرام سے بے نیاز فرما اور اپنے فضل سے تیرے سوا ہر ایک سے بے نیاز کر دے۔", translit: "Allahumma-ghnini bihalalika 'an haramik, wa bifadlika 'amman siwak" },
{ id: 124, category: "Rizq & Sustenance", arabic: "اللَّهُمَّ أَكْثِرْ مَالِي وَوَلَدِي وَبَارِكْ لِي فِيمَا آتَيْتَنِي", urdu: "اے اللہ! میرا مال اور اولاد زیادہ فرما اور جو تو نے مجھے دیا اس میں برکت عطا فرما۔", translit: "Allahumma akthir mali wa waladi wa barik li fima ataytani" },
{ id: 125, category: "Rizq & Sustenance", arabic: "وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا وَيَرْزُقْهُ مِنْ حَيْثُ لَا يَحْتَسِبُ", urdu: "جو اللہ سے تقویٰ اختیار کرے، اللہ اس کے لیے نکلنے کا راستہ بناتا ہے اور اسے ایسی جگہ سے رزق دیتا ہے جہاں سے اسے گمان بھی نہ ہو۔", translit: "Wa man yattaqillaha yaj'al lahu makhraja wa yarzuqhu min haythu la yahtasib" },
{ id: 126, category: "Rizq & Sustenance", arabic: "رَبَّنَا ارْزُقْنَا وَأَنْتَ خَيْرُ الرَّازِقِينَ", urdu: "اے ہمارے رب! ہمیں رزق عطا فرما، تو ہی بہترین رزق دینے والا ہے۔", translit: "Rabbana-rzuqna wa anta khayrur-razikin" },
{ id: 127, category: "Rizq & Sustenance", arabic: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْفَقْرِ وَالْقِلَّةِ وَالذِّلَّةِ", urdu: "اے اللہ! میں فقر، کمی اور ذلت سے تیری پناہ مانگتا ہوں۔", translit: "Allahumma inni a'udhu bika minal-faqri wal-qillah wadh-dhillah" },
{ id: 128, category: "Rizq & Sustenance", arabic: "اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ", urdu: "اے اللہ! میں تجھ سے تیرا فضل مانگتا ہوں۔", translit: "Allahumma inni as'aluka min fadlik" },
{ id: 129, category: "Rizq & Sustenance", arabic: "وَمَنْ يَتَوَكَّلْ عَلَى اللَّهِ فَهُوَ حَسْبُهُ إِنَّ اللَّهَ بَالِغُ أَمْرِهِ", urdu: "جو اللہ پر بھروسہ کرے، اللہ اس کے لیے کافی ہے، بیشک اللہ اپنا کام پورا کرنے والا ہے۔", translit: "Wa man yatawakkal 'alallahi fahuwa hasbuh, innallaha balighu amrih" },
{ id: 130, category: "Rizq & Sustenance", arabic: "اللَّهُمَّ لَا مَانِعَ لِمَا أَعْطَيْتَ، وَلَا مُعْطِيَ لِمَا مَنَعْتَ، وَلَا يَنْفَعُ ذَا الْجَدِّ مِنْكَ الْجَدُّ", urdu: "اے اللہ! جو تو نے دیا اسے کوئی نہیں روک سکتا اور جو تو نے روکا اسے کوئی نہیں دے سکتا، کسی کا مال و اختیار تیرے ہاں کام نہیں آتا۔", translit: "Allahumma la mani'a lima a'tayt, wa la mu'tiya lima mana't, wa la yanfa'u dhal-jaddi minkal-jadd" },
{ id: 131, category: "Rizq & Sustenance", arabic: "اللَّهُمَّ إِنِّي أَسْأَلُكَ أَنْ تَرْزُقَنِي رِزْقًا حَلَالًا طَيِّبًا", urdu: "اے اللہ! مجھے حلال اور پاکیزہ رزق عطا فرما۔", translit: "Allahumma inni as'aluka an tarzuqani rizqan halalan tayyiban" },
{ id: 132, category: "Rizq & Sustenance", arabic: "اللَّهُمَّ إِنِّي أَسْأَلُكَ الْهُدَى وَالتُّقَى وَالْعَفَافَ وَالْغِنَى", urdu: "اے اللہ! میں تجھ سے ہدایت، تقویٰ، پاکدامنی اور بے نیازی کا سوال کرتا ہوں۔", translit: "Allahumma inni as'alukal-huda wat-tuqa wal-'afafa wal-ghina" },

/* ---------- HEALTH & ILLNESS ---------- */
{ id: 133, category: "Health & Illness", arabic: "اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ", urdu: "اے اللہ! میں دنیا و آخرت میں عافیت کا سوال کرتا ہوں۔", translit: "Allahumma inni as'alukal-'afiyah fid-dunya wal-akhirah" },
{ id: 134, category: "Health & Illness", arabic: "اللَّهُمَّ رَبَّ النَّاسِ أَذْهِبِ الْبَأْسَ، وَاشْفِ أَنْتَ الشَّافِي، لَا شِفَاءَ إِلَّا شِفَاؤُكَ، شِفَاءً لَا يُغَادِرُ سَقَمًا", urdu: "اے اللہ! لوگوں کے رب، تکلیف دور فرما اور شفا عطا فرما، تو ہی شافی ہے، تیری شفا کے سوا کوئی شفا نہیں، ایسی شفا جو کوئی بیماری باقی نہ چھوڑے۔", translit: "Allahumma rabban-nas, adhhibil-ba's, washfi antash-shafi, la shifa'a illa shifa'uka shifa'an la yughadiru saqama" },
{ id: 135, category: "Health & Illness", arabic: "أَعُوذُ بِعِزَّةِ اللَّهِ وَقُدْرَتِهِ مِنْ شَرِّ مَا أَجِدُ وَأُحَاذِرُ", urdu: "میں اللہ کی عزت اور قدرت کے ذریعے اس چیز کے شر سے پناہ مانگتا ہوں جو میں محسوس کر رہا ہوں اور جس کا خوف ہے۔", translit: "A'udhu bi'izzatillahi wa qudratihi min sharri ma ajidu wa uhadhir" },
{ id: 136, category: "Health & Illness", arabic: "بِسْمِ اللَّهِ", urdu: "اللہ کے نام سے (بیمار پر ہاتھ پھیر کر تین بار)۔", translit: "Bismillah" },
{ id: 137, category: "Health & Illness", arabic: "اللَّهُمَّ اغْفِرْ لِي وَارْحَمْنِي وَعَافِنِي وَاهْدِنِي وَارْزُقْنِي", urdu: "اے اللہ! مجھے معاف فرما، رحم کر، عافیت دے، ہدایت دے اور رزق عطا فرما۔", translit: "Allahumma-ghfir li, warhamni, wa 'afini, wahdini, warzuqni" },
{ id: 138, category: "Health & Illness", arabic: "أَسْأَلُ اللَّهَ الْعَظِيمَ رَبَّ الْعَرْشِ الْعَظِيمِ أَنْ يَشْفِيَكَ", urdu: "میں عظیم اللہ سے جو عرش عظیم کا رب ہے، سوال کرتا ہوں کہ تجھے شفا عطا فرمائے (مریض کی عیادت پر سات بار)۔", translit: "As'alullahal-'azima rabbal-'arshil-'azimi an yashfiyak" },
{ id: 139, category: "Health & Illness", arabic: "الْحَمْدُ لِلَّهِ الَّذِي عَافَانِي مِمَّا ابْتَلَاكَ بِهِ، وَفَضَّلَنِي عَلَى كَثِيرٍ مِمَّنْ خَلَقَ تَفْضِيلًا", urdu: "شکر ہے اللہ کا جس نے مجھے اس سے عافیت دی جس میں تو مبتلا ہے اور مجھے بہت سی مخلوق پر فضیلت دی (مبتلا شخص کو دیکھ کر)۔", translit: "Alhamdu lillahil-ladhi 'afani mimmal-lubtaka bihi, wa faddalani 'ala kathirin mimman khalaqa tafdila" },
{ id: 140, category: "Health & Illness", arabic: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ زَوَالِ نِعْمَتِكَ، وَتَحَوُّلِ عَافِيَتِكَ، وَفُجَاءَةِ نِقْمَتِكَ، وَجَمِيعِ سَخَطِكَ", urdu: "اے اللہ! میں تیری نعمت کے زوال، عافیت کے بدلنے، اچانک نقمت اور تیرے سب غضب سے تیری پناہ مانگتا ہوں۔", translit: "Allahumma inni a'udhu bika min zawali ni'matika, wa tahawwuli 'afiyatika, wa fuja'ati niqmatika, wa jami'i sakhathik" },
{ id: 141, category: "Health & Illness", arabic: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْبَرَصِ وَالْجُنُونِ وَالْجُذَامِ وَسَيِّئِ الْأَسْقَامِ", urdu: "اے اللہ! میں برص، جنون، جذام اور بری بیماریوں سے تیری پناہ مانگتا ہوں۔", translit: "Allahumma inni a'udhu bika minal-barasi wal-jununi wal-juzami wa sayyi'il-asqam" },
{ id: 142, category: "Health & Illness", arabic: "لَا بَأْسَ طَهُورٌ إِنْ شَاءَ اللَّهُ", urdu: "کوئی حرج نہیں، یہ (بیماری) پاک کرنے والی ہے ان شاء اللہ (مریض سے کہنا)۔", translit: "La ba'sa tahurun insha Allah" },

/* ---------- PROTECTION ---------- */
{ id: 143, category: "Protection", arabic: "أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ غَضَبِهِ وَعِقَابِهِ، وَشَرِّ عِبَادِهِ، وَمِنْ هَمَزَاتِ الشَّيَاطِينِ وَأَنْ يَحْضُرُونِ", urdu: "میں اللہ کے مکمل کلمات سے اس کے غضب، عذاب، بندوں کے شر اور شیاطین کے وسوسوں اور ان کے پاس آنے سے پناہ مانگتا ہوں۔", translit: "A'udhu bikalimatillahit-tammati min ghadabihi wa 'iqabihi, wa sharri 'ibadihi, wa min hamazatish-shayatin wa an yahdurun" },
{ id: 144, category: "Protection", arabic: "قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ", urdu: "سورۃ الفلق پڑھنا — دن و رات کے شر اور حسد کرنے والے کے شر سے پناہ۔", translit: "Qul a'udhu bi rabbil-falaq" },
{ id: 145, category: "Protection", arabic: "قُلْ أَعُوذُ بِرَبِّ النَّاسِ", urdu: "سورۃ الناس پڑھنا — جن اور انسانوں کے وسوسے سے پناہ۔", translit: "Qul a'udhu bi rabbin-nas" },
{ id: 146, category: "Protection", arabic: "أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ", urdu: "میں اللہ سے مردود شیطان سے پناہ مانگتا ہوں۔", translit: "A'udhu billahi minash-shaytanir-rajim" },
{ id: 147, category: "Protection", arabic: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْكُفْرِ وَالدَّيْنِ", urdu: "اے اللہ! میں کفر اور قرض کے بوجھ سے تیری پناہ مانگتا ہوں۔", translit: "Allahumma inni a'udhu bika minal-kufri wad-dayn" },
{ id: 148, category: "Protection", arabic: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، وَمِنْ فِتْنَةِ الدَّجَّالِ، وَمِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ", urdu: "اے اللہ! میں قبر کے عذاب، دجال کے فتنے اور زندگی و موت کے فتنے سے تیری پناہ مانگتا ہوں۔", translit: "Allahumma inni a'udhu bika min 'adhabil-qabr, wa min fitnatid-dajjal, wa min fitnatil-mahya wal-mamat" },
{ id: 149, category: "Protection", arabic: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ مَا عَمِلْتُ وَمِنْ شَرِّ مَا لَمْ أَعْمَلْ", urdu: "اے اللہ! میں نے جو کیا اس کے شر سے اور جو نہیں کیا اس کے شر سے تیری پناہ مانگتا ہوں۔", translit: "Allahumma inni a'udhu bika min sharri ma 'amiltu wa min sharri ma lam a'mal" },
{ id: 150, category: "Protection", arabic: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ سَمْعِي، وَمِنْ شَرِّ بَصَرِي، وَمِنْ شَرِّ لِسَانِي، وَمِنْ شَرِّ قَلْبِي، وَمِنْ شَرِّ مَنِيِّي", urdu: "اے اللہ! میں اپنے کان، آنکھ، زبان، دل اور شہوت کے شر سے تیری پناہ مانگتا ہوں۔", translit: "Allahumma inni a'udhu bika min sharri sam'i, wa min sharri basari, wa min sharri lisani, wa min sharri qalbi, wa min sharri maniyyi" },
{ id: 151, category: "Protection", arabic: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ جَهْدِ الْبَلَاءِ، وَدَرَكِ الشَّقَاءِ، وَسُوءِ الْقَضَاءِ، وَشَمَاتَةِ الْأَعْدَاءِ", urdu: "اے اللہ! میں مصیبت کی سختی، بدبختی، برے فیصلے اور دشمنوں کی خوشی سے تیری پناہ مانگتا ہوں۔", translit: "Allahumma inni a'udhu bika min jahdil-bala'i, wa darakish-shaqa'i, wa su'il-qada'i, wa shamatatil-a'da'" },
{ id: 152, category: "Protection", arabic: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ مُنْكَرَاتِ الْأَخْلَاقِ وَالْأَعْمَالِ وَالْأَهْوَاءِ", urdu: "اے اللہ! میں برے اخلاق، برے اعمال اور بری خواہشوں سے تیری پناہ مانگتا ہوں۔", translit: "Allahumma inni a'udhu bika min munkaratil-akhlaqi wal-a'mali wal-ahwa'" },
{ id: 153, category: "Protection", arabic: "أَعُوذُ بِوَجْهِ اللَّهِ الْكَرِيمِ، وَبِكَلِمَاتِ اللَّهِ التَّامَّاتِ الَّتِي لَا يُجَاوِزُهُنَّ بَرٌّ وَلَا فَاجِرٌ، مِنْ شَرِّ مَا يَنْزِلُ مِنَ السَّمَاءِ وَمَا يَعْرُجُ فِيهَا، وَمِنْ شَرِّ مَا ذَرَأَ فِي الْأَرْضِ وَمَا يَخْرُجُ مِنْهَا، وَمِنْ شَرِّ فِتَنِ اللَّيْلِ وَالنَّهَارِ", urdu: "میں اللہ کے کریم چہرے اور مکمل کلمات کے ذریعے پناہ مانگتا ہوں جن سے کوئی نیک و بد آگے نہیں بڑھ سکتا، آسمان سے اترنے والے اور چڑھنے والے شر سے، زمین میں پیدا شدہ اور اس سے نکلنے والے شر سے اور دن رات کے فتنوں سے۔", translit: "A'udhu bi wajhillahil-karim, wa bikalimatillahit-tammatil-lati la yujawizuhunna barrun wa la fajir, min sharri ma yanzilu minas-sama'i wa ma ya'ruju fiha, wa min sharri ma dhara'a fil-ardi wa ma yakhruju minha, wa min sharri fitanil-layli wan-nahari" },
{ id: 154, category: "Protection", arabic: "اللَّهُمَّ احْفَظْنِي مِنْ بَيْنِ يَدَيَّ وَمِنْ خَلْفِي، وَعَنْ يَمِينِي وَعَنْ شِمَالِي، وَمِنْ فَوْقِي، وَأَعُوذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِي", urdu: "اے اللہ! مجھے میرے آگے، پیچھے، دائیں، بائیں اور اوپر سے حفاظت فرما، اور میں تیری عظمت کے ذریعے اس سے پناہ مانگتا ہوں کہ نیچے سے مجھے اچانک پکڑا جائے۔", translit: "Allahumma-hfazni min bayni yadayya wa min khalfi, wa 'an yamini wa 'an shimali, wa min fawqi, wa a'udhu bi 'azamatika an ughtala min tahti" },
/* ---------- WEATHER & NATURE ---------- */
{ id: 155, category: "Weather & Nature", arabic: "اللَّهُمَّ صَيِّبًا نَافِعًا", urdu: "اے اللہ! (بارش نازل فرما) نفع بخش مینہ۔", translit: "Allahumma sayyiban nafi'a" },
{ id: 156, category: "Weather & Nature", arabic: "اللَّهُمَّ حَوَالَيْنَا وَلَا عَلَيْنَا، اللَّهُمَّ عَلَى الْآكَامِ وَالظِّرَابِ وَبُطُونِ الْأَوْدِيَةِ وَمَنَابِتِ الشَّجَرِ", urdu: "اے اللہ! ہمارے آس پاس (بارش کر) ہم پر نہیں، اے اللہ! پہاڑوں، ٹیلوں، وادیوں اور درختوں کے اگنے کی جگہوں پر (کر)۔", translit: "Allahumma hawalayna wa la 'alayna, allahumma 'alal-akami waz-zirabi wa butunil-awdiyati wa manabitish-shajar" },
{ id: 157, category: "Weather & Nature", arabic: "اللَّهُمَّ اغْفِرْ لَنَا وَارْحَمْنَا", urdu: "اے اللہ! ہمیں معاف فرما اور ہم پر رحم فرما (کسی دھماکے یا طوفان کی آواز سن کر)۔", translit: "Allahumma-ghfir lana warhamna" },
{ id: 158, category: "Weather & Nature", arabic: "اللَّهُمَّ اسْقِنَا الْغَيْثَ وَلَا تَجْعَلْنَا مِنَ الْقَانِطِينَ", urdu: "اے اللہ! ہمیں بارش عطا فرما اور ہمیں مایوس نہ کر۔", translit: "Allahumma-sqinal-ghaytha wa la taj'alna minal-qanitin" },
{ id: 159, category: "Weather & Nature", arabic: "اللَّهُمَّ انْفَعْنَا بِبَرَكَتِهَا", urdu: "اے اللہ! ہمیں اس (بارش) کی برکت سے نفع پہنچا۔", translit: "Allahumma-nfa'na bibarakatiha" },
{ id: 160, category: "Weather & Nature", arabic: "سُبْحَانَ الَّذِي يُسَبِّحُ الرَّعْدُ بِحَمْدِهِ وَالْمَلَائِكَةُ مِنْ خِيفَتِهِ", urdu: "پاک ہے وہ ذات جس کی حمد کے ساتھ بادل کی گرج اور فرشتے اس کے ڈر سے تسبیح کرتے ہیں۔", translit: "Subhanal-ladhi yusabbihur-ra'du bihamdihi wal-mala'ikatu min khifatih" },
{ id: 161, category: "Weather & Nature", arabic: "اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَهَا وَخَيْرَ مَا فِيهَا وَخَيْرَ مَا أُرْسِلَتْ بِهِ، وَأَعُوذُ بِكَ مِنْ شَرِّهَا وَشَرِّ مَا فِيهَا وَشَرِّ مَا أُرْسِلَتْ بِهِ", urdu: "اے اللہ! میں تجھ سے ہوا کی خیر، اس میں موجود خیر اور اس کے ذریعے بھیجی گئی خیر کا سوال کرتا ہوں، اور اس کے شر، اس میں موجود شر اور اس کے ذریعے بھیجے گئے شر سے تیری پناہ مانگتا ہوں۔", translit: "Allahumma inni as'aluka khayraha wa khayra ma fiha wa khayra ma ursilat bihi, wa a'udhu bika min sharriha wa sharri ma fiha wa sharri ma ursilat bihi" },
{ id: 162, category: "Weather & Nature", arabic: "اللَّهُمَّ بِكَ أَصْبَحْنَا وَبِكَ أَمْسَيْنَا، وَبِكَ نَحْيَا وَبِكَ نَمُوتُ وَإِلَيْكَ النُّشُورُ", urdu: "اے اللہ! تیرے ہی ذریعے ہم صبح و شام کرتے ہیں، تیرے ہی ذریعے جیتے مرتے ہیں اور تیری ہی طرف اٹھنا ہے۔", translit: "Allahumma bika asbahna wa bika amsayna, wa bika nahya wa bika namutu wa ilaykan-nushur" },

/* ---------- DEATH & FUNERAL ---------- */
{ id: 163, category: "Death & Funeral", arabic: "إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ، اللَّهُمَّ أْجُرْنِي فِي مُصِيبَتِي وَأَخْلِفْ لِي خَيْرًا مِنْهَا", urdu: "بیشک ہم اللہ کے ہیں اور ہم اسی کی طرف لوٹنے والے ہیں، اے اللہ! میری مصیبت میں مجھے اجر عطا فرما اور اس سے بہتر عطا فرما۔", translit: "Inna lillahi wa inna ilayhi raji'un, allahumma'jurni fi musibati wa akhlif li khayran minha" },
{ id: 164, category: "Death & Funeral", arabic: "اللَّهُمَّ اغْفِرْ لَهُ وَارْحَمْهُ، وَعَافِهِ وَاعْفُ عَنْهُ", urdu: "اے اللہ! اسے معاف فرما، اس پر رحم کر، اسے عافیت دے اور اسے معاف کر دے (میت کے لیے)۔", translit: "Allahumma-ghfir lahu warhamhu, wa 'afihi wa'fu 'anhu" },
{ id: 165, category: "Death & Funeral", arabic: "اللَّهُمَّ اجْعَلْ قَبْرَهُ رَوْضَةً مِنْ رِيَاضِ الْجَنَّةِ، وَلَا تَجْعَلْهُ حُفْرَةً مِنْ حُفَرِ النَّارِ", urdu: "اے اللہ! اس کی قبر کو جنت کے باغوں میں سے ایک باغ بنا اور آگ کے گڑھوں میں سے گڑھا نہ بنا۔", translit: "Allahumma-j'al qabrahur-rawdatan min riyadil-jannah, wa la taj'alhu hufratan min hufarin-nar" },
{ id: 166, category: "Death & Funeral", arabic: "اللَّهُمَّ أَعِنِّي عَلَى غَمِّي وَهَمِّي", urdu: "اے اللہ! میرے غم اور اندیشے میں میری مدد فرما (مصیبت میں)۔", translit: "Allahumma a'inni 'ala ghammi wa hammi" },
{ id: 167, category: "Death & Funeral", arabic: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ ضِيقِ الدُّنْيَا وَضِيقِ يَوْمِ الْقِيَامَةِ", urdu: "اے اللہ! میں دنیا کی تنگی اور قیامت کے دن کی تنگی سے تیری پناہ مانگتا ہوں۔", translit: "Allahumma inni a'udhu bika min diqid-dunya wa diqi yawmil-qiyamah" },
{ id: 168, category: "Death & Funeral", arabic: "اللَّهُمَّ إِنِّي أَسْأَلُكَ حُسْنَ الْخَاتِمَةِ", urdu: "اے اللہ! میں تجھ سے اچھا انجام کا سوال کرتا ہوں۔", translit: "Allahumma inni as'aluka husnal-khatimah" },
{ id: 169, category: "Death & Funeral", arabic: "اللَّهُمَّ لَا تَجْعَلْ مُصِيبَتَنَا فِي دِينِنَا، وَلَا تَجْعَلِ الدُّنْيَا أَكْبَرَ هَمِّنَا", urdu: "اے اللہ! ہماری مصیبت کو ہمارے دین میں نہ بنا اور دنیا کو ہمارا سب سے بڑا غم نہ بنا۔", translit: "Allahumma la taj'al musibatana fi dinina, wa la taj'alid-dunya akbara hammina" },
{ id: 170, category: "Death & Funeral", arabic: "اللَّهُمَّ اغْسِلْهُ بِالْمَاءِ وَالثَّلْجِ وَالْبَرَدِ، وَنَقِّهِ مِنَ الذُّنُوبِ كَمَا يُنَقَّى الثَّوْبُ الْأَبْيَضُ مِنَ الدَّنَسِ", urdu: "اے اللہ! اسے پانی، برف اور اولے سے دھو دے اور گناہوں سے اس طرح پاک کر دے جیسے سفید کپڑا میل سے پاک کیا جاتا ہے۔", translit: "Allahumma-ghsilhu bil-ma'i wath-thalji wal-barad, wa naqqihi minadh-dhunubi kama yunaqqath-thawbul-abyadu minad-danas" },

/* ---------- PRAISE & GRATITUDE ---------- */
{ id: 171, category: "Praise & Gratitude", arabic: "الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ", urdu: "تمام تعریفیں اللہ کے لیے ہیں جو تمام جہانوں کا رب ہے۔", translit: "Alhamdu lillahi rabbil-'alamin" },
{ id: 172, category: "Praise & Gratitude", arabic: "سُبْحَانَ اللَّهِ وَبِحَمْدِهِ، سُبْحَانَ اللَّهِ الْعَظِيمِ", urdu: "اللہ پاک ہے اور اسی کی حمد ہے، اللہ عظیم پاک ہے۔", translit: "Subhanallahi wa bihamdih, subhanallahil-'azim" },
{ id: 173, category: "Praise & Gratitude", arabic: "سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَلَا إِلَهَ إِلَّا اللَّهُ، وَاللَّهُ أَكْبَرُ", urdu: "اللہ پاک ہے، حمد اللہ کے لیے، اللہ کے سوا کوئی معبود نہیں اور اللہ سب سے بڑا ہے۔", translit: "Subhanallahi, walhamdu lillahi, wa la ilaha illallahu, wallahu akbar" },
{ id: 174, category: "Praise & Gratitude", arabic: "لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ", urdu: "نہ تو طاقت ہے نہ قوت سوائے اللہ کے۔", translit: "La hawla wa la quwwata illa billah" },
{ id: 175, category: "Praise & Gratitude", arabic: "سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، وَتَبَارَكَ اسْمُكَ، وَتَعَالَى جَدُّكَ، وَلَا إِلَهَ غَيْرُكَ", urdu: "پاک ہے تو اے اللہ اور تیری حمد ہے، تیرا نام بابرکت ہے، تیری شان بلند ہے اور تیرے سوا کوئی معبود نہیں۔", translit: "Subhanaka allahumma wa bihamdik, wa tabaraka-ismuk, wa ta'ala jadduk, wa la ilaha ghayruk" },
{ id: 176, category: "Praise & Gratitude", arabic: "رَبِّ أَوْزِعْنِي أَنْ أَشْكُرَ نِعْمَتَكَ الَّتِي أَنْعَمْتَ عَلَيَّ", urdu: "اے میرے رب! مجھے توفیق دے کہ میں تیری نعمت کا شکر ادا کروں جو تو نے مجھ پر کی۔", translit: "Rabbi awzi'ni an ashkura ni'matakal-lati an'amta 'alayya" },
{ id: 177, category: "Praise & Gratitude", arabic: "اللَّهُمَّ لَكَ الْحَمْدُ كَمَا يَنْبَغِي لِجَلَالِ وَجْهِكَ وَعَظِيمِ سُلْطَانِكَ", urdu: "اے اللہ! تیری ہی حمد ہے جیسا تیرے جلالِ چہرے اور عظیم سلطنت کے لائق ہے۔", translit: "Allahumma lakal-hamdu kama yanbaghi li jalami wajhika wa 'azimi sultanik" },
{ id: 178, category: "Praise & Gratitude", arabic: "سُبْحَانَ اللَّهِ عَدَدَ خَلْقِهِ، وَسُبْحَانَ اللَّهِ رِضَا نَفْسِهِ، وَسُبْحَانَ اللَّهِ زِنَةَ عَرْشِهِ، وَسُبْحَانَ اللَّهِ مِدَادَ كَلِمَاتِهِ", urdu: "اللہ پاک ہے جتنی اس کی مخلوق ہے، اللہ پاک ہے جتنی اس کی رضا، اللہ پاک ہے جتنا اس کا عرش اور اللہ پاک ہے جتنی اس کے کلمات کی سیاہی۔", translit: "Subhanallahi 'adada khalqihi, wa subhanallahi rida nafsihi, wa subhanallahi zinata 'arshihi, wa subhanallahi midada kalimatih" },

/* ---------- JANNAH & JAHANNAM ---------- */
{ id: 179, category: "Jannah & Jahannam", arabic: "اللَّهُمَّ إِنِّي أَسْأَلُكَ الْجَنَّةَ وَأَعُوذُ بِكَ مِنَ النَّارِ", urdu: "اے اللہ! میں تجھ سے جنت کا سوال کرتا ہوں اور آگ سے تیری پناہ مانگتا ہوں۔", translit: "Allahumma inni as'alukal-jannata wa a'udhu bika minan-nar" },
{ id: 180, category: "Jannah & Jahannam", arabic: "اللَّهُمَّ أَدْخِلْنِي الْجَنَّةَ بِغَيْرِ حِسَابٍ", urdu: "اے اللہ! مجھے بغیر حساب جنت میں داخل فرما۔", translit: "Allahumma adkhilnil-jannata bighayri hisab" },
{ id: 181, category: "Jannah & Jahannam", arabic: "اللَّهُمَّ إِنِّي أَسْأَلُكَ الْفِرْدَوْسَ الْأَعْلَى مِنَ الْجَنَّةِ", urdu: "اے اللہ! میں تجھ سے جنت کا سب سے اعلیٰ مقام فردوس مانگتا ہوں۔", translit: "Allahumma inni as'alukal-firdawsal-a'la minal-jannah" },
{ id: 182, category: "Jannah & Jahannam", arabic: "رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ", urdu: "اے ہمارے رب! ہمیں دنیا میں بھلائی اور آخرت میں بھلائی عطا فرما اور آگ کے عذاب سے بچا۔", translit: "Rabbana atina fid-dunya hasanatan wa fil-akhirati hasanatan wa qina 'adhaban-nar" },
{ id: 183, category: "Jannah & Jahannam", arabic: "اللَّهُمَّ اجْعَلْنِي مِنْ أَهْلِ الْجَنَّةِ", urdu: "اے اللہ! مجھے جنت والوں میں سے بنا۔", translit: "Allahumma-j'alni min ahlil-jannah" },
{ id: 184, category: "Jannah & Jahannam", arabic: "اللَّهُمَّ إِنِّي أَسْأَلُكَ رِضَاكَ وَالْجَنَّةَ، وَأَعُوذُ بِكَ مِنْ سَخَطِكَ وَالنَّارِ", urdu: "اے اللہ! میں تجھ سے تیری رضا اور جنت کا سوال کرتا ہوں اور تیرے غضب اور آگ سے تیری پناہ مانگتا ہوں۔", translit: "Allahumma inni as'aluka ridaka wal-jannah, wa a'udhu bika min sakhathika wan-nar" },
{ id: 185, category: "Jannah & Jahannam", arabic: "اللَّهُمَّ حَرِّمْ وَجْهِي عَلَى النَّارِ", urdu: "اے اللہ! میرے چہرے کو آگ پر حرام فرما۔", translit: "Allahumma harrim wajhi 'alan-nar" },
{ id: 186, category: "Jannah & Jahannam", arabic: "اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ وَرَحْمَتِكَ فَإِنَّهُ لَا يَمْلِكُهَا إِلَّا أَنْتَ", urdu: "اے اللہ! میں تجھ سے تیرا فضل اور تیری رحمت کا سوال کرتا ہوں، بیشک ان کا مالک صرف تو ہی ہے۔", translit: "Allahumma inni as'aluka min fadlika wa rahmatik, fa innahu la yamlikuha illa anta" },
{ id: 187, category: "Jannah & Jahannam", arabic: "اللَّهُمَّ اجْعَلْنِي مِنْ عِبَادِكَ الصَّالِحِينَ", urdu: "اے اللہ! مجھے اپنے نیک بندوں میں سے بنا۔", translit: "Allahumma-j'alni min 'ibadikas-salihin" },
{ id: 188, category: "Jannah & Jahannam", arabic: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ النَّارِ وَعَذَابِ الْقَبْرِ", urdu: "اے اللہ! میں آگ کے عذاب اور قبر کے عذاب سے تیری پناہ مانگتا ہوں۔", translit: "Allahumma inni a'udhu bika min 'adhabin-nari wa 'adhabil-qabr" },

/* ---------- GENERAL & DAILY LIFE ---------- */
{ id: 189, category: "General & Daily Life", arabic: "رَبَّنَا تَقَبَّلْ مِنَّا إِنَّكَ أَنْتَ السَّمِيعُ الْعَلِيمُ", urdu: "اے ہمارے رب! ہم سے قبول فرما، بیشک تو ہی سننے والا جاننے والا ہے۔", translit: "Rabbana taqabbal minna innaka antas-sami'ul-'alim" },
{ id: 190, category: "General & Daily Life", arabic: "اللَّهُمَّ إِنِّي أَسْأَلُكَ الْهُدَى وَالصَّلَاحَ", urdu: "اے اللہ! میں تجھ سے ہدایت اور اصلاح کا سوال کرتا ہوں۔", translit: "Allahumma inni as'alukal-huda was-salah" },
{ id: 191, category: "General & Daily Life", arabic: "اللَّهُمَّ اهْدِنِي وَسَدِّدْنِي", urdu: "اے اللہ! مجھے ہدایت فرما اور راستی عطا فرما۔", translit: "Allahumma-hdini wa saddidni" },
{ id: 192, category: "General & Daily Life", arabic: "اللَّهُمَّ إِنَّا نَسْتَعِينُكَ وَنَسْتَغْفِرُكَ وَنُثْنِي عَلَيْكَ الْخَيْرَ", urdu: "اے اللہ! ہم تیری مدد مانگتے ہیں، تجھ سے معافی مانگتے ہیں اور تیری خیر کی تعریف بیان کرتے ہیں۔", translit: "Allahumma inna nasta'inuka wa nastaghfiruka wa nuthni 'alaykal-khayr" },
{ id: 193, category: "General & Daily Life", arabic: "اللَّهُمَّ لَا تَدَعْ لِي ذَنْبًا إِلَّا غَفَرْتَهُ، وَلَا هَمًّا إِلَّا فَرَّجْتَهُ، وَلَا حَاجَةً مِنْ حَوَائِجِ الدُّنْيَا وَالْآخِرَةِ إِلَّا قَضَيْتَهَا", urdu: "اے اللہ! کوئی گناہ نہ چھوڑ جسے تو معاف نہ کرے، کوئی غم نہ چھوڑ جسے تو نہ دور کرے اور دنیا و آخرت کی کوئی حاجت نہ چھوڑ جو تو پوری نہ کرے۔", translit: "Allahumma la tada' li dhanban illa ghafartah, wa la hamman illa farrajtah, wa la hajatan min hawa'ijid-dunya wal-akhirati illa qadaytaha" },
{ id: 194, category: "General & Daily Life", arabic: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ، وَالْجُبْنِ وَالْبُخْلِ، وَالْهَرَمِ وَعَذَابِ الْقَبْرِ", urdu: "اے اللہ! میں عاجزی، سستی، بزدلی، بخیلی، بڑھاپے کی کمزوری اور قبر کے عذاب سے تیری پناہ مانگتا ہوں۔", translit: "Allahumma inni a'udhu bika minal-'ajzi wal-kasal, wal-jubni wal-bukhl, wal-harami wa 'adhabil-qabr" },
{ id: 195, category: "General & Daily Life", arabic: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَالْعَجْزِ وَالْكَسَلِ، وَالْجُبْنِ وَالْبُخْلِ، وَضَلَعِ الدَّيْنِ وَغَلَبَةِ الرِّجَالِ", urdu: "اے اللہ! میں غم و اندوہ، عاجزی، سستی، بزدلی، بخیلی، قرض کے بوجھ اور لوگوں کے غلبہ سے تیری پناہ مانگتا ہوں۔", translit: "Allahumma inni a'udhu bika minal-hammi wal-hazan, wal-'ajzi wal-kasal, wal-jubni wal-bukhl, wa dhala'id-dayni wa ghalabatir-rijal" },
{ id: 196, category: "General & Daily Life", arabic: "اللَّهُمَّ أَصْلِحْ لِي دِينِي الَّذِي هُوَ عِصْمَةُ أَمْرِي، وَأَصْلِحْ لِي دُنْيَايَ الَّتِي فِيهَا مَعَاشِي، وَأَصْلِحْ لِي آخِرَتِي الَّتِي فِيهَا مَعَادِي", urdu: "اے اللہ! میرا دین درست فرما جو میرے معاملے کی حفاظت ہے، میری دنیا درست فرما جس میں میری روزی ہے، اور میری آخرت درست فرما جس میں میرا لوٹنا ہے۔", translit: "Allahumma aslih li dini alladhi huwa 'ismatu amri, wa aslih li dunyaya allati fiha ma'ashi, wa aslih li akhirati allati fiha ma'adi" },
{ id: 197, category: "General & Daily Life", arabic: "اللَّهُمَّ اجْعَلْ أَوْسَعَ رِزْقِكَ عَلَيَّ عِنْدَ كِبَرِ سِنِّي وَانْقِضَاءِ عُمُرِي", urdu: "اے اللہ! میرا سب سے وسیع رزق میرے بڑھاپے اور عمر کے ختم ہونے پر بنا۔", translit: "Allahumma-j'al awsa'a rizqika 'alayya 'inda kibari sinni wanqida'i 'umuri" },
{ id: 198, category: "General & Daily Life", arabic: "اللَّهُمَّ إِنِّي أَسْأَلُكَ الثَّبَاتَ فِي الْأَمْرِ وَالْعَزِيمَةَ عَلَى الرُّشْدِ", urdu: "اے اللہ! میں تجھ سے معاملے میں ثبات اور راستی پر پختہ ارادے کا سوال کرتا ہوں۔", translit: "Allahumma inni as'alukath-thabata fil-amri wal-'azimata 'alar-rushd" },
{ id: 199, category: "General & Daily Life", arabic: "اللَّهُمَّ إِنِّي أَسْأَلُكَ حُبَّكَ، وَحُبَّ مَنْ يُحِبُّكَ، وَحُبَّ عَمَلٍ يُقَرِّبُنِي إِلَى حُبِّكَ", urdu: "اے اللہ! میں تجھ سے تیری محبت، ان کی محبت جو تجھ سے محبت کریں اور ایسے عمل کی محبت کا سوال کرتا ہوں جو مجھے تیری محبت کے قریب کرے۔", translit: "Allahumma inni as'aluka hubbak, wa hubba man yuhibbuk, wa hubba 'amalin yuqarribuni ila hubbik" },
{ id: 200, category: "General & Daily Life", arabic: "رَبَّنَا إِنَّنَا سَمِعْنَا مُنَادِيًا يُنَادِي لِلْإِيمَانِ أَنْ آمِنُوا بِرَبِّكُمْ فَآمَنَّا، رَبَّنَا فَاغْفِرْ لَنَا ذُنُوبَنَا وَكَفِّرْ عَنَّا سَيِّئَاتِنَا وَتَوَفَّنَا مَعَ الْأَبْرَارِ", urdu: "اے ہمارے رب! ہم نے پکارنے والے کو ایمان کی طرف پکارتے سنا، پس ہم ایمان لائے، اے ہمارے رب! ہمارے گناہ معاف فرما، ہماری برائیاں مٹا اور ہمیں نیک بندوں کے ساتھ وفات دے۔", translit: "Rabbana innana sami'na munadiyan yunadi lil-imani an aminu birabbikum fa amanna, rabbana faghfir lana dhunubana wa kaffir 'anna sayyi'atina wa tawaffana ma'al-abrar" },
];
